    if (pObj != NULL) {
        for (j = 0, iTypeOffset = 0, iElementOffset = 0;
             j < pObj->xNbElements;
             iTypeOffset += 2, iElementOffset += 4, j++) {
            if (*(short*)(pObj->d_xListOfElementsTypes + iTypeOffset) != 1) {
                continue;
            }
            p_stEIT = *(GEO_tdstElementIndexedTriangles_**)(pObj->d_stListOfElements + iElementOffset);
