                        p_stDynamic, hSupObj, xDT);
                } else {
                    MTH3D_M_vCopyVector((MTH3D_tdstVector_*)&hCurrentMatrix->stTransformMatrix.stCol_3, (MTH3D_tdstVector_*)&stVector);
                    hCurrentMatrix->stTransformMatrix.stCol_3.xW = 1.0f;
