                        }
                    }

                    else if (MEC_fn_bCollision(&lObstacle, g_a_stObstacle,
                                          p_stDynamic, hSupObj,
                                          hCurrentMatrix, hCurrentMatrix, 1)) {
                        MEC_fn_vDeleteBaseBackFace(
                            lObstacle, g_a_stObstacle, p_stDynamic);
