void fn_vXorEncrypt(unsigned char* _LastKey, int length, int direction)
{
    int i;
    unsigned char* p;
    unsigned int pval;
    unsigned int val2;
    unsigned int val;
    int last_val;

    i = 0;
    p = _LastKey;
    if (direction < 0)
    {
        p = _LastKey + length - 1;
        i = length - 1;
        length = -1;
    }
    val = 0;
    last_val = 0;
    while (i != length)
    {
        pval = *p;
        val2 = val ^ last_val;
        last_val = val;
        *p = pval ^ val2;
        val = (val + pval + 2 - direction) & 0x1f;
        i += direction;
        p += direction;
    }
}

