void J_New_GetInterpolPointOnEdge(J_New_ParticleFace_* pFace, J_New_InterpolPoint_* pPoint, unsigned int Edge, float U)
{
    float A[4];
    int p2;
    int p1;

    if (Edge == 0) { p1 = 0; p2 = 1; }
    else if (Edge == 1) { p1 = 1; p2 = 2; }
    else if (Edge == 2) { p1 = 2; p2 = 0; }
    else p1 = 0;

    A[1] = (U - pFace->pUVs[p1][0]) / (pFace->pUVs[p2][0] - pFace->pUVs[p1][0]);
    A[0] = 1.0f - A[1];

    {
        float* pP1 = pFace->pPoints[p1];
        float* pP2 = pFace->pPoints[p2];
        float* pC1 = pFace->pColors[p1];
        float* pC2 = pFace->pColors[p2];
        float* pA = A;
        float* pPos = pPoint->Pos;
        float* pColor = pPoint->Color;

        /* VU0 macro-mode interpolation: no C form. */
        asm {
            lqc2 vf2, 0x0(pP1)
            lqc2 vf3, 0x0(pP2)
            lqc2 vf4, 0x0(pC1)
            lqc2 vf5, 0x0(pC2)
            lqc2 vf6, 0x0(pA)
            vmulx.xyz vf8, vf2, vf6
            vmuly.xyz vf9, vf3, vf6
            vsubx.w vf12, vf0, vf0
            vmulx.xyzw vf10, vf4, vf6
            vmuly.xyzw vf11, vf5, vf6
            vadd.xyz vf12, vf8, vf9
            vadd.xyzw vf13, vf10, vf11
            sqc2 vf12, 0x0(pPos)
            sqc2 vf13, 0x0(pColor)
        }
    }

    pPoint->UVs[0] = U;
    pPoint->UVs[1] = A[0] * pFace->pUVs[p1][1] + A[1] * pFace->pUVs[p2][1];
}

unsigned int fn_uiGetSomeBytes(unsigned int* _puiArray, unsigned int NbInts, unsigned int SomeOtherValue)
{
    unsigned int Seeds[6];
    unsigned int i;
    unsigned int j;

    Seeds[0] = g_uiAnotherRandom;
    Seeds[1] = g_stEngineStructure.ulRealTimeLowPart;
    Seeds[2] = g_stEngineStructure.ulTrameNumber;
    Seeds[3] = (unsigned int)(12345.0f * g_stEngineStructure.h_StdCamCaracter->hGlobalMatrix->xTranslationY);
    Seeds[4] = (unsigned int)_puiArray;
    Seeds[5] = SomeOtherValue;

    for (i = 0; i < NbInts; i++)
    {
        Seeds[0] = (Seeds[0] * 0x126CDD7 + 0x1E240) | 1;
        for (j = 1; j < 6; j++)
            Seeds[j] = Seeds[j - 1] ^ ((Seeds[j] + (Seeds[j - 1] >> 7)) * 0x127C3D1);
        _puiArray[i] = Seeds[5];
    }

    return _puiArray[i - 1];
}

void GLI_vCalculateLightingMatricesGhost(void)
{
    MAT_tdstTransformation_ TempMat;
    float fNorm;
    MTH3D_tdstVector_ stVect2;
    MTH3D_tdstVector_ stVect;

    {
        float* pZero = vZeroVect;
        float (*pPositions)[4] = GLI_g_LightPositions;
        float (*pColors)[4] = GLI_g_LightColors;

        /* VU0 quadword copies: lqc2/sqc2 have no C form. */
        asm {
            lqc2 vf1, 0x0(pZero)
            sqc2 vf1, 0x20(pPositions)
            sqc2 vf1, 0x30(pPositions)
            sqc2 vf1, 0x20(pColors)
            sqc2 vf1, 0x30(pColors)
        }
    }
    {
        float* pDst = GLI_g_AmbientLight;
        float* pSrc = GhostAmbient;

        asm {
            lqc2 vf1, 0x0(pSrc)
            sqc2 vf1, 0x0(pDst)
        }
    }

    stVect.xX = 0.0f;
    stVect.xY = 0.0f;
    stVect.xZ = 1.0f;

    MAT_fn_vInvert(&TempMat, (MAT_tdstTransformation_*)GLI_BIG_GLOBALS_gs_st_CameraMatrix);
    MAT_fn_vApplyOnVector(&stVect2, &TempMat, &stVect);

    fNorm = stVect2.xX * stVect2.xX + stVect2.xY * stVect2.xY + stVect2.xZ * stVect2.xZ;
    fNorm = 1.0f / fNorm;

    stVect2.xX = stVect2.xX * fNorm;
    stVect2.xY = stVect2.xY * fNorm;
    stVect2.xZ = stVect2.xZ * fNorm;

    GLI_g_LightPositions[0][0] = -stVect2.xX;
    GLI_g_LightPositions[0][1] = -stVect2.xY;
    GLI_g_LightPositions[0][2] = -stVect2.xZ;
    GLI_g_LightPositions[0][3] = 0.0f;
    GLI_g_LightPositions[1][0] = stVect2.xX;
    GLI_g_LightPositions[1][1] = stVect2.xY;
    GLI_g_LightPositions[1][2] = stVect2.xZ;
    GLI_g_LightPositions[1][3] = 0.0f;

    {
        float (*pColors)[4] = GLI_g_LightColors;
        float* pParallel1 = GhostParallel1;
        float* pParallel2 = GhostParallel2;

        asm {
            lqc2 vf1, 0x0(pParallel1)
            lqc2 vf2, 0x0(pParallel2)
            sqc2 vf1, 0x0(pColors)
            sqc2 vf2, 0x10(pColors)
        }
    }

    sceVu0TransposeMatrix(GLI_g_LightPositions, GLI_g_LightPositions);
}

MTH_stRotation* MTH_p_stRotationComputeRotationWith2Vectors(MTH_stRotation* _p_stResult, MTH3D_tdstVector_* _p_stSrcUnitVector, MTH3D_tdstVector_* _p_stImaUnitVector)
{
    float xNorm;
    MTH3D_tdstVector_* p_stAxis;

    p_stAxis = &_p_stResult->m_stAxis;

    p_stAxis->xX = _p_stSrcUnitVector->xY * _p_stImaUnitVector->xZ - _p_stSrcUnitVector->xZ * _p_stImaUnitVector->xY;
    p_stAxis->xY = _p_stSrcUnitVector->xZ * _p_stImaUnitVector->xX - _p_stSrcUnitVector->xX * _p_stImaUnitVector->xZ;
    p_stAxis->xZ = _p_stSrcUnitVector->xX * _p_stImaUnitVector->xY - _p_stSrcUnitVector->xY * _p_stImaUnitVector->xX;

    if (MTH_xAbs(p_stAxis->xX) < 1e-5f && MTH_xAbs(p_stAxis->xY) < 1e-5f && MTH_xAbs(p_stAxis->xZ) < 1e-5f)
    {
        if (MTH_xAbs(_p_stSrcUnitVector->xX - _p_stImaUnitVector->xX) < 1e-5f && MTH_xAbs(_p_stSrcUnitVector->xY - _p_stImaUnitVector->xY) < 1e-5f && MTH_xAbs(_p_stSrcUnitVector->xZ - _p_stImaUnitVector->xZ) < 1e-5f)
        {
            _p_stResult->m_xAngle = 0.0f; p_stAxis->xX = 0.0f; p_stAxis->xY = 0.0f; p_stAxis->xZ = 0.0f;
            return _p_stResult;
        }
        _p_stResult->m_xAngle = 3.1415927f;
        return _p_stResult;
    }

    xNorm = MTH_xSqrt(MTH3D_xSqrVector(p_stAxis)); if (xNorm != 0.0f) { xNorm = 1.0f / xNorm; p_stAxis->xX = xNorm * p_stAxis->xX; p_stAxis->xY = xNorm * p_stAxis->xY; p_stAxis->xZ = xNorm * p_stAxis->xZ; }

    xNorm = MTH3D_xDotProductVector(_p_stSrcUnitVector, _p_stImaUnitVector);
    if (xNorm <= -1.0f)
    {
        _p_stResult->m_xAngle = 3.1415927f;
        return _p_stResult;
    }
    if (xNorm >= 1.0f)
    {
        _p_stResult->m_xAngle = 0.0f; p_stAxis->xX = 0.0f; p_stAxis->xY = 0.0f; p_stAxis->xZ = 0.0f;
        return _p_stResult;
    }

    _p_stResult->m_xAngle = acosf(xNorm);

    return _p_stResult;
}

