void PS2_fn_vEnterCriticalSection(_stCriticalSection* p_stCS)
{
    int r;
    int MyThreadId;
    int toto;

    toto = 0;
    MyThreadId = GetThreadId();
    r = p_stCS->Sid;
    if (PollSema(r) == r)
    {
        p_stCS->ReentrancyCount = 0;
        p_stCS->OwnerThreadId = MyThreadId;
        asm {
        .set noreorder
        mtc0 toto, $24
        }
    }
    else if (MyThreadId == p_stCS->OwnerThreadId)
    {
        p_stCS->ReentrancyCount++;
    }
    else
    {
        WaitSema(p_stCS->Sid);
        p_stCS->ReentrancyCount = 0;
        p_stCS->OwnerThreadId = MyThreadId;
        asm { mtc0 toto, $24 }
    }
}

void fn_vPlayNewLipsSynchro(tdstAChannel_* p_stChannel, tdstFamilyList_* p_stFamily)
{
    int bNoEnd;
    char cPhonem;
    MTH3D_tdstVector_ stVector;
    static char cLastPhonem;
    static unsigned long ulTrameCounter;
    static MTH3D_tdstVector_ stLastVector;

    cPhonem = (char)SND_fn_s32GetLastMarker();
    bNoEnd = fn_bGetVectorFromPhonem(&stVector, cPhonem, p_stFamily);
    if (bNoEnd)
    {
        if (cLastPhonem != cPhonem)
        {
            ulTrameCounter = 0;
            fn_bGetVectorFromPhonem(&stLastVector, cLastPhonem, p_stFamily);
            cLastPhonem = cPhonem;
        }
        if (cPhonem != '*')
        {
            switch (ulTrameCounter)
            {
            case 0:
            stVector.xX = stLastVector.xX + 0.33f * (stVector.xX - stLastVector.xX);
            stVector.xY = stLastVector.xY + 0.33f * (stVector.xY - stLastVector.xY);
            stVector.xZ = stLastVector.xZ + 0.33f * (stVector.xZ - stLastVector.xZ);
                break;
            case 1:
            stVector.xX = stLastVector.xX + 0.66f * (stVector.xX - stLastVector.xX);
            stVector.xY = stLastVector.xY + 0.66f * (stVector.xY - stLastVector.xY);
            stVector.xZ = stLastVector.xZ + 0.66f * (stVector.xZ - stLastVector.xZ);
                break;
            }
            ulTrameCounter++;
            MAT_fn_vSetScale(p_stChannel->hSupObject->hLocalMatrix, &stVector);
        }
    }
    else
    {
        p_stChannel->bLipsChannel = 0;
        MAT_fn_vRemoveScale(p_stChannel->hSupObject->hLocalMatrix, p_stChannel->hSupObject->hLocalMatrix);
        cLastPhonem = '*';
    }
}

void fn_vInitAllEvents(HIE_tdstSuperObject_* p_stSuperObject, unsigned short uwFirstFrame)
{
    unsigned char ucMemoryType;
    unsigned char bBTLevel;
    unsigned char i;
    tdstEvent_* p_stEvent;
    tdstAnim3d_* p_stAnim;
    tdst3dData_* h_3dData;

    ucMemoryType = 0;
    bBTLevel = 0;
    if (fn_bIsInFix((p_stSuperObject->ulTypeOfLinkedObject != 2) ? NULL : p_stSuperObject->hLinkedObject.p_stCharacter) && !GAM_fn_bIsEngineInFixMode())
    {
        ucMemoryType = HMU_fn_ucGetActualNormalMemoryBlockUsed();
        HMU_fn_vSetMemoriesInFixMode();
        bBTLevel = 1;
    }

    h_3dData = p_stSuperObject->hLinkedObject.p_stCharacter->h_3dData;
    if (h_3dData->h_CurrentState)
    {
        p_stAnim = fn_p_stGetAnimInState(h_3dData->h_CurrentState);
        p_stEvent = fn_p_GetEventsAddress(p_stAnim, uwFirstFrame, h_3dData->h_CurrentObjectsTable);
        if (p_stEvent)
        {
            h_3dData->d_ucEventActivation = (unsigned char*)HMU_fn_p_vMalloc(p_stAnim->ucNumberOfEvents, 1);
            if (uwFirstFrame)
            {
                for (i = 0; i < p_stAnim->ucNumberOfEvents && p_stEvent[i].uwFrameNumber < uwFirstFrame; i++)
                    ;
                h_3dData->ucNextEvent = i;
            }
            else if (fn_scGetSpeedInState(h_3dData->h_CurrentState) > 0)
            {
                h_3dData->ucNextEvent = 0;
            }
            else
            {
                h_3dData->ucNextEvent = p_stAnim->ucNumberOfEvents - 1;
            }
            for (i = 0; i < p_stAnim->ucNumberOfEvents; i++)
            {
                h_3dData->d_ucEventActivation[i] = p_stEvent->p_stfEventInTBL->ucFirstCall;
                p_stEvent++;
            }
        }
        if (bBTLevel)
        {
            if (ucMemoryType == HMU_fn_ucGetLevelNormalMemoryBlock())
                HMU_fn_vSetMemoriesInLevelMode();
            else if (fn_lGetTransitionBloc() != 1)
                HMU_fn_vSetMemoriesInTransition1Mode();
            else
                HMU_fn_vSetMemoriesInTransition2Mode();
        }
    }
}

void GLI_vGsStoreFrameBufferInto128x128x16__FPUssiis(unsigned short* _DestinationBuffer, short vram, int WIDTH, int HEIGHT, short CurrentPSM)
{
    sceGsStoreImage StoreImage;
    unsigned char* p_ucLine;
    unsigned char* p_ucPixel;
    sceDmaChan* p_stDmaVif;
    int y;
    int iLine;
    unsigned int x;
    int iColumn;

    p_ucLine = (unsigned char*)malloc(WIDTH * 4);
    p_stDmaVif = sceDmaGetChan(1);
    sceDmaGetChan(2);
    if (CurrentPSM == 0x31)
        CurrentPSM = 0x30;
    if (CurrentPSM == 1)
        CurrentPSM = 0;
    for (y = 0, iLine = 0; y < 256; y += 2, iLine++)
    {
        sceGsSetDefStoreImage(&StoreImage, vram, WIDTH / 64, CurrentPSM, 0, y, WIDTH, 1);
        FlushCache(0);
        sceGsExecStoreImage(&StoreImage, p_ucLine);
        sceGsSyncPath(0, 0);
        InvalidDCache(p_ucLine, p_ucLine + WIDTH * 4);
        p_stDmaVif->chcr.TTE = 1;
        p_ucPixel = p_ucLine;
        for (x = 0, iColumn = 0; x < 256; x += 2, iColumn++)
        {
            _DestinationBuffer[iColumn + iLine * 128] = ((unsigned int)p_ucPixel[0] >> 3) + ((((unsigned int)p_ucPixel[2] >> 3) << 10) + 0x8000 + (((unsigned int)p_ucPixel[1] >> 3) << 5));
            p_ucPixel += 8;
        }
    }
    free(p_ucLine);
}

int PIC_bIntersectSegmentWithCollideObject(MTH3D_tdstVector_* p_stCameraPos, MTH3D_tdstVector_* p_stVertex12, COL_tdstCollideObject_* p_stObject, PIC_tdstPickedObject_* p_stPickedObject)
{
    short i;
    MTH3D_tdstVector_ stSouris3D;
    MTH3D_tdstVector_ stTemp;
    int bReturn;
    int bTest;
    short xNbElements;

    MTH3D_M_vAddVector(&stSouris3D, p_stCameraPos, p_stVertex12);
    bReturn = 0;
    bTest = INT_fn_bIntersectSegmentWithFaceOfCollideObject(p_stCameraPos, &stSouris3D, p_stVertex12, p_stObject, 3, &xNbElements, p_stPickedObject->aDEF_stDataOfElement);
    if (bTest)
    {
        MAT_fn_vApplyOnVertex(&stTemp, g_p_stCurrentMatrix, p_stCameraPos);
        for (i = 0; i < xNbElements; i++)
        {
            MAT_fn_vApplyOnVertex(&p_stPickedObject->aDEF_stDataOfElement[i].stHit, g_p_stCurrentMatrix, &p_stPickedObject->aDEF_stDataOfElement[i].stHit);
            p_stPickedObject->aDEF_stDataOfElement[i].xDistance = MTH3D_M_xVectorGap(&stTemp, &p_stPickedObject->aDEF_stDataOfElement[i].stHit);
        }
        p_stPickedObject->xNbElements = xNbElements;
        bReturn = 1;
        p_stPickedObject->xModePicking = PIC_C_ModePickingFace;
    }
    return bReturn;
}

void GEO_fn_vAddObjectToSphere(GEO_tdstGeometricObject_* _hGeometricObject, MTH3D_tdstVector_* _p_stSphereCenter, float* _p_xSphereRadius)
{
    MTH3D_tdstVector_ stSphereCenterLocal;
    GEO_tdstElementSprite_* p_stLocalElementSprite;
    GEO_tdstElementSpheres_* p_stLocalElementSphere;
    int lElementCounter;
    int i;
    MTH3D_tdstVector_* p_stVertex;

    p_stVertex = _hGeometricObject->d_stListOfPoints;
    for (i = 0; i < _hGeometricObject->xNbPoints; i++, p_stVertex++)
    {
        GEO_fn_vComputeBoundingSphereOfOneSphereAndOnePoint(_p_stSphereCenter, _p_xSphereRadius, _p_stSphereCenter, *_p_xSphereRadius, p_stVertex);
    }

    for (lElementCounter = 0; lElementCounter < _hGeometricObject->xNbElements; lElementCounter++)
    {
        switch (((short*)_hGeometricObject->d_xListOfElementsTypes)[lElementCounter])
        {
        case 3:
            p_stLocalElementSprite = ((GEO_tdstElementSprite_**)_hGeometricObject->d_stListOfElements)[lElementCounter];
            for (i = 0; i < p_stLocalElementSprite->xNbSprites; i++)
            {
                float xX;
                float xY;
                float xSqrNorm;
                float xRadius;

                xX = p_stLocalElementSprite->d_stListOfSprites[i].stSize.xX * (p_stLocalElementSprite->d_stListOfSprites[i].hSprite->d_xSizeOfSprite->xX + p_stLocalElementSprite->d_stListOfSprites[i].hSprite->d_xDisplacementOfSprite->xX);
                xY = p_stLocalElementSprite->d_stListOfSprites[i].stSize.xY * (p_stLocalElementSprite->d_stListOfSprites[i].hSprite->d_xSizeOfSprite->xY + p_stLocalElementSprite->d_stListOfSprites[i].hSprite->d_xDisplacementOfSprite->xY);
                stSphereCenterLocal = _hGeometricObject->d_stListOfPoints[p_stLocalElementSprite->d_stListOfSprites[i].xCenterPoint];
                MTH_SQR2_TO(xSqrNorm, xX, xY) MTH_SQRT_TO(xRadius, xSqrNorm)
                GEO_fn_vComputeBoundingSphereOfTwoSpheres(_p_stSphereCenter, _p_xSphereRadius, _p_stSphereCenter, *_p_xSphereRadius, &stSphereCenterLocal, xRadius);
            }
            break;
        case 7:
            p_stLocalElementSphere = ((GEO_tdstElementSpheres_**)_hGeometricObject->d_stListOfElements)[lElementCounter];
            for (i = 0; i < p_stLocalElementSphere->xNbSpheres; i++)
            {
                stSphereCenterLocal = _hGeometricObject->d_stListOfPoints[p_stLocalElementSphere->d_stListOfSpheres[i].xCenterPoint];
                GEO_fn_vComputeBoundingSphereOfTwoSpheres(_p_stSphereCenter, _p_xSphereRadius, _p_stSphereCenter, *_p_xSphereRadius, &stSphereCenterLocal, p_stLocalElementSphere->d_stListOfSpheres[i].xRadius);
            }
            break;
        case 8:
        case 9:
            break;
        }
    }
}

int strFileOpen(anon_0* file, char* filename)
{
    int ret;
    char* body = NULL;
    char fn[256];
    char devname[64];

    body = index(filename, ':');
    if (body)
    {
        int dlen;

        dlen = body - filename;
        strncpy(devname, filename, dlen);
        devname[dlen] = 0;
        body += 1;
        if (!strcmp(devname, "cdrom0"))
        {
            int i;
            int len = strlen(body);
            const char* tail;

            file->isOnCD = 1;
            for (i = 0; i < len; i++)
            {
                if (body[i] == '/')
                    body[i] = '\\';
                body[i] = toupper(body[i]);
            }
            tail = (index(filename, ';')) ? "" : ";1";
            sprintf(fn, "%s%s", body, tail);
        }
        else
        {
            file->isOnCD = 0;
            sprintf(fn, "%s:%s", devname, body);
        }
    }
    else
    {
        body = filename;
        strcpy(devname, "host0");
        file->isOnCD = 0;
        sprintf(fn, "%s:%s", devname, body);
    }

    printf("file: %s\n", fn);

    if (file->isOnCD)
    {
        anon_2 mode;

        if (!isStrFileInit)
            isStrFileInit = 1;
        file->iopBuf = (int)sceSifAllocIopHeap(2048 * 80 + 16);
        sceCdStInit(80, 5, (file->iopBuf + 15) & ~15);
        sceCdMmode(PS2_fn_iGetCDMediaMode());
        sceCdDiskReady(0);
        while (!SCEECdSearchFile(&last_video_fd, fn))
            ;
        file->fp.lsn = last_video_fd.pos;
        file->fp.size = last_video_fd.size;
        file->fp.name[0] = 0;
        file->size = file->fp.size;
        mode.trycount = 0;
        mode.spindlctrl = 0;
        mode.datapattern = 0;
        while (!sceCdStStart(file->fp.lsn, &mode))
        {
            asm { mtc0 zero, $24 }
        }
        return 1;
    }
    else
    {
        sceCdDiskReady(0);
        file->fd = sceOpen(fn, 1);
        if (file->fd < 0)
        {
            printf("Cannot open '%s'(sceOpen)\n", fn);
            return 0;
        }
        sceCdDiskReady(0);
        file->size = sceLseek(file->fd, 0, 2);
        if (file->size < 0)
        {
            printf("sceLseek() fails (%s): %d\n", fn, file->size);
            sceClose(file->fd);
            return 0;
        }
        sceCdDiskReady(0);
        ret = sceLseek(file->fd, 0, 0);
        if (ret < 0)
        {
            printf("sceLseek() fails (%s)\n", fn);
            sceClose(file->fd);
            return 0;
        }
    }
    return 1;
}

unsigned char INT_fn_bIntersectSemiAxeWithSphere(MTH3D_tdstVector_* p_stVertex1, MTH3D_tdstVector_* p_stVect12, MTH3D_tdstVector_* p_stSphereCenter, float xSphereRadius, unsigned char* bBack, float* p_xT, MTH3D_tdstVector_* p_stHit, MTH3D_tdstVector_* p_stNormal)
{
    float xInvR;
    float xT1;
    float xT2;
    float xB;

    if (!INT_fn_bFastRejectIntersectSemiaxeWithSphere(p_stVertex1, p_stVect12, p_stSphereCenter, xSphereRadius))
        return 0;

    {
        float xDx;
        float xDy;
        float xDz;
        float xVx;
        float xVy;
        float xVz;
        float xA;

        xDx = p_stVertex1->xX - p_stSphereCenter->xX; xDy = p_stVertex1->xY - p_stSphereCenter->xY; xDz = p_stVertex1->xZ - p_stSphereCenter->xZ;
        xVx = p_stVect12->xX; xVy = p_stVect12->xY; xVz = p_stVect12->xZ;
        MTH_DOT3_TO(xA, xVx, xVy, xVz, xVx, xVy, xVz)
        MTH_DOT3_TO(xB, xVx, xVy, xVz, xDx, xDy, xDz)
        xB = xB + xB;
        switch (INT_fn_xTrinomeResolution(xA, xB, MTH3D_M_xSqrNormMinusSqr(xDx, xDy, xDz, xSphereRadius), &xT1, &xT2))
        {
        case 2:
            *p_xT = MTH_M_xMin(xT1, xT2);
            if (0.0f <= *p_xT)
            {
                *bBack = 0;
                xInvR = 1.0f / xSphereRadius;
        p_stHit->xX = p_stVertex1->xX + *p_xT * p_stVect12->xX;
        p_stHit->xY = p_stVertex1->xY + *p_xT * p_stVect12->xY;
        p_stHit->xZ = p_stVertex1->xZ + *p_xT * p_stVect12->xZ;
        p_stNormal->xX = p_stHit->xX - p_stSphereCenter->xX;
        p_stNormal->xY = p_stHit->xY - p_stSphereCenter->xY;
        p_stNormal->xZ = p_stHit->xZ - p_stSphereCenter->xZ;
        p_stNormal->xX = xInvR * p_stNormal->xX;
        p_stNormal->xY = xInvR * p_stNormal->xY;
        p_stNormal->xZ = xInvR * p_stNormal->xZ;
        return 1;
            }
            *p_xT = MTH_M_xMax(xT1, xT2);
            if (0.0f <= *p_xT)
            {
                *bBack = 1;
                xInvR = 1.0f / xSphereRadius;
        p_stHit->xX = p_stVertex1->xX + *p_xT * p_stVect12->xX;
        p_stHit->xY = p_stVertex1->xY + *p_xT * p_stVect12->xY;
        p_stHit->xZ = p_stVertex1->xZ + *p_xT * p_stVect12->xZ;
        p_stNormal->xX = p_stHit->xX - p_stSphereCenter->xX;
        p_stNormal->xY = p_stHit->xY - p_stSphereCenter->xY;
        p_stNormal->xZ = p_stHit->xZ - p_stSphereCenter->xZ;
        p_stNormal->xX = xInvR * p_stNormal->xX;
        p_stNormal->xY = xInvR * p_stNormal->xY;
        p_stNormal->xZ = xInvR * p_stNormal->xZ;
        return 1;
            }
            break;
        case 1:
            if (0.0f <= xT1)
            {
                *bBack = 1;
                xInvR = 1.0f / xSphereRadius;
                *p_xT = xT1;
        p_stHit->xX = p_stVertex1->xX + *p_xT * p_stVect12->xX;
        p_stHit->xY = p_stVertex1->xY + *p_xT * p_stVect12->xY;
        p_stHit->xZ = p_stVertex1->xZ + *p_xT * p_stVect12->xZ;
        p_stNormal->xX = p_stHit->xX - p_stSphereCenter->xX;
        p_stNormal->xY = p_stHit->xY - p_stSphereCenter->xY;
        p_stNormal->xZ = p_stHit->xZ - p_stSphereCenter->xZ;
        p_stNormal->xX = xInvR * p_stNormal->xX;
        p_stNormal->xY = xInvR * p_stNormal->xY;
        p_stNormal->xZ = xInvR * p_stNormal->xZ;
        return 1;
            }
            break;
        }
        return 0;
    }
}

