void GLI_xSerialProjection(GLI_tdstCamera_* p_stCam, int lNbOfVertex, MTH4D_tdstVector_* p_stSource, GLI_tdstAligned2DVector_* p_stDest)
{
    GLI_tdstAligned2DVector_* p_stDestLast;
    int lNewX;
    int lVertexIndex;
    float xInterm;

    { float xTmp = 8000.0f; lNewX = *(int*)&xTmp; }
    p_stDestLast = p_stDest + lNbOfVertex;
    switch (p_stCam->lCameraMode)
    {
    case 0x66:
    case 0x67:
        for (; p_stDest < p_stDestLast; p_stDest++, p_stSource++)
        {
            if (*(int*)&p_stSource->xZ < *(int*)&p_stCam->xNear)
            {
                *(unsigned int*)&p_stDest->xOoZ |= 0x80000000;
                *(unsigned int*)&p_stDest->xX = lNewX | ((*(unsigned int*)&p_stSource->xX & 0x80000000) ^ 0x80000000);
                *(unsigned int*)&p_stDest->xY = lNewX | ((*(unsigned int*)&p_stSource->xY & 0x80000000) ^ 0x80000000);
            }
            else
            {
                p_stDest->xOoZ = 1.0f / p_stSource->xZ;
                xInterm = p_stCam->xScreen * p_stDest->xOoZ;
                p_stDest->xOoZ *= 0.25f;
                p_stDest->xX = p_stCam->stTrans.xX + xInterm * (p_stSource->xX * p_stCam->stScale.xX);
                p_stDest->xY = p_stCam->stTrans.xY + xInterm * (p_stSource->xY * p_stCam->stScale.xY);
            }
        }
        break;
    case 0x64:
    case 0x65:
        for (lVertexIndex = 0; lVertexIndex < lNbOfVertex; lVertexIndex++)
        {
            if (!(p_stSource[lVertexIndex].xZ < p_stCam->xNear))
            {
                p_stDest[lVertexIndex].xOoZ = 1.0f;
                p_stDest[lVertexIndex].xX = p_stCam->stTrans.xX + p_stCam->stScale.xX * p_stSource[lVertexIndex].xX;
                p_stDest[lVertexIndex].xY = p_stCam->stTrans.xY + p_stCam->stScale.xY * p_stSource[lVertexIndex].xY;
            }
        }
        break;
    }
}

void PS2glSetInteger(unsigned int pname, int param)
{
    int iRealBlockCount;
    int I;

    switch (pname)
    {
    case 0x420:
        g_PS2glContext.iFrameCount = param;
        if (param % 2 == 0)
        {
            g_PS2glContext.iFrameBufferFront = g_PS2glContext.iFrameBuffer1;
            g_PS2glContext.iFrameBufferBack = g_PS2glContext.iFrameBuffer0;
        }
        else
        {
            g_PS2glContext.iFrameBufferFront = g_PS2glContext.iFrameBuffer0;
            g_PS2glContext.iFrameBufferBack = g_PS2glContext.iFrameBuffer1;
        }
        break;
    case 0x421:
        g_PS2glContext.iDepthBuffer = param;
        break;
    case 0x422:
        g_PS2glContext.iDepthBufferBitDepth = param;
        break;
    case 0x423:
        g_PS2glContext.iFrameBufferBitDepth = param;
        break;
    case 0x430:
        g_PS2glContext.iFrameBuffer0 = param;
        break;
    case 0x431:
        g_PS2glContext.iFrameBuffer1 = param;
        break;
    case 0x438:
        g_PS2glContext.bFrameMode = (param == 1);
        break;
    case 0x440:
    {
        tagGLtexblock theDefaultTexBlock = { 0x3ff, 0, 0 };

        iRealBlockCount = (0x400000 - (param + 0x400)) / 4096;
        theDefaultTexBlock.nLength = iRealBlockCount;
        if (iRealBlockCount <= 0)
            printf("Fatal error: Improper buffer setting runs out of VRAM! There's no room for texture!\n");
        g_PS2glContext.iMaxTexBlockCount = iRealBlockCount;
        for (I = 0; I < 604; I++)
            g_PS2glContext.aBlockMap[I] = theDefaultTexBlock;
        g_PS2glContext.nTexMemBegin = param;
        break;
    }
    }
}

