        return 0;
    if (p_stPoint->xX > p_stMaxPoint->xX)
        return 0;
    if (p_stPoint->xY < p_stMinPoint->xY)
        return 0;
    if (p_stPoint->xY > p_stMaxPoint->xY)
        return 0;
    if (p_stPoint->xZ < p_stMinPoint->xZ)
        return 0;
    return !(p_stPoint->xZ > p_stMaxPoint->xZ);
}

