unsigned int fn_ulSizeOfDsgVar(tdeDsgVarTypeId_ eDsgVarTypeId, unsigned char ucNbElt)
{
    if(eDsgVarTypeId >= (unsigned int)eNbDsgVarType){
        return 0;
    }

    switch(eDsgVarTypeId){
        case eDsgVarType_Boolean:
        return 4;

    case eDsgVarType__128To127:
    case eDsgVarType_0To255:
        return 1;

    case eDsgVarType__32768To32767:
    case eDsgVarType_0To65535:
        return 2;

    case eDsgVarType_Integer:
    case eDsgVarType_PositiveInteger:
    case eDsgVarType_Float:
    case eDsgVarType_List:
    case eDsgVarType_Comport:
    case eDsgVarType_Action:
    case eDsgVarType_Caps:
    case eDsgVarType_Input:
    case eDsgVarType_SoundEvent:
    case eDsgVarType_Light:
    case eDsgVarType_GameMaterial:
    case eDsgVarType_VisualMaterial:
    case eDsgVarType_Perso:
    case eDsgVarType_WayPoint:
    case eDsgVarType_Graph:
    case eDsgVarType_Text:
    case eDsgVarType_SuperObject:
    case eDsgVarType_SOLinks:
        return 4;

    case eDsgVarType_Vector:
        return 12;

    case eDsgVarType_IntegerArray:
    case eDsgVarType_FloatArray:
    case eDsgVarType_PersoArray:
    case eDsgVarType_WayPointArray:
    case eDsgVarType_GraphArray:
    case eDsgVarType_TextArray:
    case eDsgVarType_SuperObjectArray:
    case eDsgVarType_SOLinksArray:
        return ((unsigned int)ucNbElt - 1) * 4 + 12;

    case eDsgVarType_VectorArray:
        return (unsigned int)ucNbElt * 12 + 8;

    default:
        return 0;
    }
    /* TODO: decompile from asm/... */
}

tdstNodeInterpret_* fn_p_stDefaultActionInit(HIE_tdstSuperObject_* p_SuperObjPerso, tdstNodeInterpret_* p_stTree)
{
    char* szTypeParam;
    unsigned char ucNbParam;
    unsigned char ucParam;
    char cType;
    tdstGetSetParam_ stParam;

    szTypeParam = szGetMetaActionTypeInParamFromId(p_stTree[-1].uDummy.uId.eMetaActionId);
    ucNbParam = strlen(szTypeParam);
    ucParam = 0;

    if (ucNbParam != 0) {
        while (ucParam < ucNbParam) {
            p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stParam);
            cType = toupper(szTypeParam[ucParam]);

            if (cType == "L"[0]) {
                fn_vSetActionParamlValue(
                    ucParam,
                    p_SuperObjPerso,
                    stParam.eType == E_vt_Float
                        ? MTH_M_xRealToLong(stParam.uDummy.uParam.xValue)
                        : stParam.uDummy.uParam.lValue);
            } else if (cType == "X"[0]) {
                fn_vSetActionParamxValue(
                    ucParam,
                    p_SuperObjPerso,
                    stParam.eType == E_vt_Float
                        ? stParam.uDummy.uParam.xValue
                        : (float)stParam.uDummy.uParam.lValue);
            } else if (cType == "V"[0]) {
                fn_vSetActionParamp_stVertex(ucParam, p_SuperObjPerso, &stParam.uDummy.uParam.stVectorValue);
            } else if (cType == "A"[0]) {
                fn_vSetActionParamStateValue(ucParam, p_SuperObjPerso, stParam.uDummy.uParam.tdxstHandleToState);
            }
            ucParam++;
        }
    }

    return p_stTree;
}

