                    hElement->hSubAnimInUse->hPrevBrotherDyn = NULL;
                    hElement->hSubAnimInUse->hFatherDyn = NULL;
                }
                fn_vDesInitAllSubEvents(p_stSuperObjCine, hElement->hSubAnimInUse);
                HMU_fn_vFree((void**)&hElement->hSubAnimInUse, 1);
