void fn_vStopEngineCinematics(CINE_tdstCine_* hCine)
{
    AI_tdstMind_* p_stMind;
    tdstStandardGame_* hStdGame;
    tdstSubAnimInUse_* hNextSubAnimInUse;
    tdstSubAnimInUse_* hSubAnimInUse;
    tdst3dData_* h_Current3dData;
    HIE_tdstSuperObject_* p_stSuperObjCine;
    CINE_tdstCineActor_* hElement;

    for (hElement = hCine->hActorList.hFirstElementDyn; hElement != NULL; hElement = hElement->hNextBrotherDyn)
    {
        CINE_CheckEndCineActor(hElement);
        if (hElement->bPlayingAnim)
        {
            break;
        }
    }
    if (hElement == NULL)
    {
        return;
    }

    hElement = hCine->hActorList.hFirstElementDyn;
    while (hElement != NULL)
    {
        if (hElement->bPlayingAnim)
        {
            p_stSuperObjCine = fn_h_StandardGameGetSuperObject(hElement->p_stActor->h_StandardGame);
            hStdGame = ((tdstEngineObject_*)p_stSuperObjCine->hLinkedObject.p_stCharacter)->h_StandardGame;
            if (hElement->bIsASubAnim)
            {
                h_Current3dData = ((tdstEngineObject_*)p_stSuperObjCine->hLinkedObject.p_stCharacter)->h_3dData;
                hSubAnimInUse = h_Current3dData->hForSubAnimInUseArray.hFirstElementDyn;
                hNextSubAnimInUse = NULL;
                if (hSubAnimInUse != NULL)
                {
                    hNextSubAnimInUse = hSubAnimInUse->hNextBrotherDyn;
                }
                if (hSubAnimInUse == hElement->hSubAnimInUse)
                {
                    if (hElement->hSubAnimInUse->hNextBrotherDyn != NULL)
                    {
                        hElement->hSubAnimInUse->hNextBrotherDyn->hPrevBrotherDyn = hElement->hSubAnimInUse->hPrevBrotherDyn;
                    }
                    if (hElement->hSubAnimInUse->hPrevBrotherDyn != NULL)
                    {
                        hElement->hSubAnimInUse->hPrevBrotherDyn->hNextBrotherDyn = hElement->hSubAnimInUse->hNextBrotherDyn;
                    }
                    if (hElement->hSubAnimInUse->hFatherDyn != NULL)
                    {
                        hElement->hSubAnimInUse->hFatherDyn->lNumberOfElementsDyn--;
                        if (hElement->hSubAnimInUse->hFatherDyn->hFirstElementDyn == hElement->hSubAnimInUse)
                        {
                            hElement->hSubAnimInUse->hFatherDyn->hFirstElementDyn = hElement->hSubAnimInUse->hNextBrotherDyn;
                        }
                        if (hElement->hSubAnimInUse->hFatherDyn->hLastElementDyn == hElement->hSubAnimInUse)
                        {
                            hElement->hSubAnimInUse->hFatherDyn->hLastElementDyn = hElement->hSubAnimInUse->hNextBrotherDyn;
                        }
                    }
                    hElement->hSubAnimInUse->hNextBrotherDyn = NULL;
                    hElement->hSubAnimInUse->hPrevBrotherDyn = NULL;
                    hElement->hSubAnimInUse->hFatherDyn = NULL;
                }
                fn_vDesInitAllSubEvents(p_stSuperObjCine, hElement->hSubAnimInUse);
                HMU_fn_vFree((void**)&hElement->hSubAnimInUse, 1);
                hSubAnimInUse = hNextSubAnimInUse;
                if (hSubAnimInUse != NULL)
                {
                    PLA_fn_bSetNewState(p_stSuperObjCine, hElement->p_stStateAfterCine, 1, 0, 0, 0, 0.0f, 0);
                }
            }
            else
            {
                PLA_fn_bSetNewState(p_stSuperObjCine, hElement->p_stStateAfterCine, 1, 0, 0, 0, 0.0f, 0);
            }
            if ((h_Current3dData->h_CurrentCineActor->bPreviousIAState == 0) && (h_Current3dData->h_CurrentCineActor->bSkipIA != 0))
            {
                hStdGame->ulCustomBits &= 0xFFFEFFFF;
            }
            if ((h_Current3dData->h_CurrentCineActor->bPreviousMecaState == 0) && (h_Current3dData->h_CurrentCineActor->bSkipMeca != 0))
            {
                hStdGame->ulCustomBits &= 0xFFFF7FFF;
            }
            if (hElement->bChangeComportEnd)
            {
                if (hElement->p_stIntelEnd != NULL)
                {
                    p_stMind = ((tdstEngineObject_*)p_stSuperObjCine->hLinkedObject.p_stCharacter)->h_Brain->p_stMind;
                    fn_vInternalChangeComportProcedure(p_stMind->p_stIntelligence, hElement->p_stIntelEnd, (unsigned char)(p_stMind->bDoingIntel != 0));
                }
            }
            if (hElement->bChangeReflexEnd)
            {
                if (hElement->p_stReflexBegin != NULL)
                {
                    p_stMind = ((tdstEngineObject_*)p_stSuperObjCine->hLinkedObject.p_stCharacter)->h_Brain->p_stMind;
                    fn_vInternalChangeComportProcedure(p_stMind->p_stReflex, hElement->p_stReflexEnd, (unsigned char)(p_stMind->bDoingIntel != 0));
                }
            }
            CINE_SendRequestsEndSounds(hElement);
            hStdGame->ulAICustomBits &= 0xFF7FFFFF;
            hElement->p_stStateDuringCine->p_stAnim = NULL;
        }
        hElement = hElement->hNextBrotherDyn;
    }
}

void MAT_fn_vSetRotationMatrix(MAT_tdstTransformation_* _hTransform, MTH3D_tdstMatrix_* _p_stRotationMatrix)
{
    MTH4D_tdstMatrix_ TmpMat;
    float xQX;
    float xQY;
    float xQZ;
    float xQW;
    float xZoom;

    switch (_hTransform->eType)
    {
    case MAT_eTransform_Identity:
    case MAT_eTransform_Translation:
        _hTransform->eType = MAT_eTransform_Rotation;
        /* fall through */
    case MAT_eTransform_Rotation:
        MAT_M_vSetRotationVector(_hTransform->stTransformMatrix.stCol_0, &_p_stRotationMatrix->stCol_0);
        MAT_M_vSetRotationVector(_hTransform->stTransformMatrix.stCol_1, &_p_stRotationMatrix->stCol_1);
        MAT_M_vSetRotationVector(_hTransform->stTransformMatrix.stCol_2, &_p_stRotationMatrix->stCol_2);
        _hTransform->stTransformMatrix.stCol_0.xW = 0.0f;
        _hTransform->stTransformMatrix.stCol_1.xW = 0.0f;
        _hTransform->stTransformMatrix.stCol_2.xW = 0.0f;
        break;

    case MAT_eTransform_Zoom:
        _hTransform->eType = MAT_eTransform_RotationZoom;
        /* fall through */
    case MAT_eTransform_RotationZoom:
        xZoom = _hTransform->stScaleVector.xX;
        MAT_M_vScaleRotationVector(_hTransform->stTransformMatrix.stCol_0, &_p_stRotationMatrix->stCol_0, xZoom);
        MAT_M_vScaleRotationVector(_hTransform->stTransformMatrix.stCol_1, &_p_stRotationMatrix->stCol_1, xZoom);
        MAT_M_vScaleRotationVector(_hTransform->stTransformMatrix.stCol_2, &_p_stRotationMatrix->stCol_2, xZoom);
        break;

    case MAT_eTransform_Scale:
        _hTransform->eType = MAT_eTransform_RotationScale;
        /* fall through */
    case MAT_eTransform_RotationScale:
        MAT_M_vScaleRotationVector(_hTransform->stTransformMatrix.stCol_0, &_p_stRotationMatrix->stCol_0, _hTransform->stScaleVector.xX);
        MAT_M_vScaleRotationVector(_hTransform->stTransformMatrix.stCol_1, &_p_stRotationMatrix->stCol_1, _hTransform->stScaleVector.xY);
        MAT_M_vScaleRotationVector(_hTransform->stTransformMatrix.stCol_2, &_p_stRotationMatrix->stCol_2, _hTransform->stScaleVector.xZ);
        break;

    case MAT_eTransform_ComplexRotationScale:
        MAT_fn_vQuatToMatrix(&TmpMat, _hTransform->stScaleVector.xX, _hTransform->stScaleVector.xY, _hTransform->stScaleVector.xZ, _hTransform->stScaleVector.xW);
        MAT_M_vTransposeRotationMatrix(TmpMat);
        MTH4D_fn_vSpecializedMulMatrixMatrixWithoutBuffer(&_hTransform->stTransformMatrix, &TmpMat, &_hTransform->stTransformMatrix);
        MAT_M_vCopyRotationMatrix(TmpMat, _p_stRotationMatrix);
        MTH4D_fn_vSpecializedMulMatrixMatrixWithoutBuffer(&_hTransform->stTransformMatrix, &TmpMat, &_hTransform->stTransformMatrix);
        MAT_fn_v_MatrixToQuat(&TmpMat, &xQX, &xQY, &xQZ, &xQW);
        _hTransform->stScaleVector.xX = xQX;
        _hTransform->stScaleVector.xY = xQY;
        _hTransform->stScaleVector.xZ = xQZ;
        _hTransform->stScaleVector.xW = xQW;
        break;
    }
}

void impPS2glFogfv(unsigned int pname, float* params)
{
    int ivFogColor[4];

    if (pname == 0x0B66) /* GL_FOG_COLOR */
    {
        ivFogColor[0] = (int)(255.0f * fogClamp01(params[0]));
        ivFogColor[1] = (int)(255.0f * fogClamp01(params[1]));
        ivFogColor[2] = (int)(255.0f * fogClamp01(params[2]));

        *(tag_int4*)&g_PS2glContext.ivFogColor = *(tag_int4*)ivFogColor;

        g_gsContext.FOGCOL.FCR = (char)ivFogColor[0]; g_gsContext.ModFlgs.FOGCOL_Modified = 1;
        g_gsContext.FOGCOL.FCG = (char)ivFogColor[1]; g_gsContext.ModFlgs.FOGCOL_Modified = 1;
        g_gsContext.FOGCOL.FCB = (char)ivFogColor[2]; g_gsContext.ModFlgs.FOGCOL_Modified = 1;

        if (pname != 0x0B66)
        {
            switch (pname)
            {
            case 0x0B65: /* GL_FOG_MODE */
                g_PS2glContext.eFogMode = ivFogColor[0];
                break;
            case 0x0B62: /* GL_FOG_DENSITY */
                g_PS2glContext.fFogDensity = (float)ivFogColor[0];
                break;
            case 0x0B63: /* GL_FOG_START */
                g_PS2glContext.fFogLinearStart = (float)ivFogColor[0];
                break;
            case 0x0B64: /* GL_FOG_END */
                g_PS2glContext.fFogLinearEnd = (float)ivFogColor[0];
                break;
            case 0x0B61: /* GL_FOG_INDEX */
                g_PS2glContext.fFogIndex = (float)ivFogColor[0];
                break;
            default:
                return;
            }
            g_PS2glContext.bFogChanged = 1;
        }
    }
    else
    {
        float fValue = params[0];
        switch (pname)
        {
        case 0x0B65: /* GL_FOG_MODE */
            /* The retail code inlines the float-to-unsigned conversion; spell
             * it out so the compiler does not call fptoui. */
            if (2147483648.0f <= fValue)
            {
                g_PS2glContext.eFogMode = 0x80000000u | (unsigned int)(int)(fValue - 2147483648.0f);
            }
            else
            {
                g_PS2glContext.eFogMode = (unsigned int)(int)fValue;
            }
            break;
        case 0x0B62: /* GL_FOG_DENSITY */
            g_PS2glContext.fFogDensity = fValue;
            break;
        case 0x0B63: /* GL_FOG_START */
            g_PS2glContext.fFogLinearStart = fValue;
            break;
        case 0x0B64: /* GL_FOG_END */
            g_PS2glContext.fFogLinearEnd = fValue;
            break;
        case 0x0B61: /* GL_FOG_INDEX */
            g_PS2glContext.fFogIndex = fValue;
            break;
        default:
            return;
        }
        g_PS2glContext.bFogChanged = 1;
    }
}

void fn_vLaunchEngineCinematics(CINE_tdstCine_* hCine)
{
