void MAT_fn_vNormalize(MAT_tdstTransformation_* _hTransform)
{
    MTH4D_tdstMatrix_* p_stMatrix;
    MTH4D_tdstMatrix_ TmpMat;
    MTH4D_tdstMatrix_* p_stMat;
    MTH4D_tdstVector_* p_stCol0;
    MTH4D_tdstVector_* p_stCol1;
    MTH4D_tdstVector_* p_stCol2;
    MTH4D_tdstVector_* p_stCol3;

    switch (_hTransform->eType)
    {
    case MAT_eTransform_Uninitialized:
    case MAT_eTransform_Identity:
    case MAT_eTransform_Translation:
        break;

    case MAT_eTransform_Zoom:
    case MAT_eTransform_Scale:
        _hTransform->eType = MAT_eTransform_Translation;
        MAT_M_vSetIdentityRotationMatrix(_hTransform);
        _hTransform->stScaleVector.xX = 1.0f;
        _hTransform->stScaleVector.xY = 1.0f;
        _hTransform->stScaleVector.xZ = 1.0f;
        _hTransform->stScaleVector.xW = 1.0f;
        break;

    case MAT_eTransform_RotationZoom:
    case MAT_eTransform_RotationScale:
        MAT_fn_vRemoveScale(_hTransform, _hTransform);
        /* fall through */
    case MAT_eTransform_Rotation:
        p_stMatrix = &_hTransform->stTransformMatrix;
        MAT_M_vSetCrossVector(_hTransform->stTransformMatrix.stCol_1,
                              _hTransform->stTransformMatrix.stCol_0.xX,
                              _hTransform->stTransformMatrix.stCol_0.xY,
                              _hTransform->stTransformMatrix.stCol_0.xZ,
                              _hTransform->stTransformMatrix.stCol_2.xX,
                              _hTransform->stTransformMatrix.stCol_2.xY,
                              _hTransform->stTransformMatrix.stCol_2.xZ);
        MAT_M_vNormalizeVector(&p_stMatrix->stCol_0);
        MAT_M_vNormalizeVector(&p_stMatrix->stCol_1);
        MAT_M_vSetCrossVector(p_stMatrix->stCol_2,
                              p_stMatrix->stCol_1.xX,
                              p_stMatrix->stCol_1.xY,
                              p_stMatrix->stCol_1.xZ,
                              p_stMatrix->stCol_0.xX,
                              p_stMatrix->stCol_0.xY,
                              p_stMatrix->stCol_0.xZ);
        MAT_M_vSetZeroW(p_stMatrix);
        break;

    case MAT_eTransform_ComplexRotationScale:
        p_stMatrix = &_hTransform->stTransformMatrix;
        MAT_fn_vQuatToMatrix(&TmpMat, _hTransform->stScaleVector.xX, _hTransform->stScaleVector.xY, _hTransform->stScaleVector.xZ, _hTransform->stScaleVector.xW);
        p_stCol0 = &TmpMat.stCol_0;
        p_stCol1 = &TmpMat.stCol_1;
        p_stCol2 = &TmpMat.stCol_2;
        p_stCol3 = &TmpMat.stCol_3;
        MAT_COPY_VECTOR(*p_stCol3, p_stMatrix->stCol_3);
        MAT_COPY_VECTOR(p_stMatrix->stCol_0, *p_stCol0);
        MAT_COPY_VECTOR(p_stMatrix->stCol_1, *p_stCol1);
        MAT_COPY_VECTOR(p_stMatrix->stCol_2, *p_stCol2);
        MAT_COPY_VECTOR(p_stMatrix->stCol_3, *p_stCol3);
        MAT_M_vSetCrossVector(p_stMatrix->stCol_1,
                              p_stMatrix->stCol_0.xX,
                              p_stMatrix->stCol_0.xY,
                              p_stMatrix->stCol_0.xZ,
                              p_stMatrix->stCol_2.xX,
                              p_stMatrix->stCol_2.xY,
                              p_stMatrix->stCol_2.xZ);
        MAT_M_vNormalizeVector(&p_stMatrix->stCol_0);
        MAT_M_vNormalizeVector(&p_stMatrix->stCol_1);
        MAT_M_vSetCrossVector(p_stMatrix->stCol_2,
                              p_stMatrix->stCol_1.xX,
                              p_stMatrix->stCol_1.xY,
                              p_stMatrix->stCol_1.xZ,
                              p_stMatrix->stCol_0.xX,
                              p_stMatrix->stCol_0.xY,
                              p_stMatrix->stCol_0.xZ);
        MAT_M_vSetZeroW(p_stMatrix);
        _hTransform->stScaleVector.xX = 1.0f;
        _hTransform->stScaleVector.xY = 1.0f;
        _hTransform->stScaleVector.xZ = 1.0f;
        _hTransform->stScaleVector.xW = 1.0f;
        _hTransform->eType = MAT_eTransform_Rotation;
        break;
    }
}

void AGO2_MEM_FreeFromHandle(unsigned int Handle)
{
    unsigned int HandleDescIndex;
    unsigned int j;
    AGO2_MEM_HandleDescriptors_* pCurrentDescriptor;
    void* pBlock;
    void* pEnd;
    unsigned int FreeZoneAfter;
    unsigned int FreeZoneBefore;
    unsigned int k;

    FreeZoneBefore = 1000;
    FreeZoneAfter = 1000;
    for (HandleDescIndex = 0; HandleDescIndex < g_AGO2_MEM_NbOfAllocatedBlocs; HandleDescIndex++) {
        if (g_AGO2_MEM_HandleDescriptors[HandleDescIndex].Handle == Handle) {
            break;
        }
    }
    if (HandleDescIndex == g_AGO2_MEM_NbOfAllocatedBlocs) {
        printf("HEHO !!! CA VA PAS LA TETE !!??\n\n");
        return;
    }

    pCurrentDescriptor = &g_AGO2_MEM_HandleDescriptors[HandleDescIndex];
    pBlock = (void*)pCurrentDescriptor->Pointer;
    pEnd = (void*)(pCurrentDescriptor->Pointer + pCurrentDescriptor->Size);

    for (k = 0; k < g_AGO2_MEM_NumberOfFreeZones; k++) {
        if (g_AGO2_MEM_FreeZones[k].pStart == (int)pEnd) {
            FreeZoneAfter = k;
        }
        else if (g_AGO2_MEM_FreeZones[k].pEnd == (int)pBlock) {
            FreeZoneBefore = k;
        }
    }

    if ((FreeZoneAfter != 1000) || (FreeZoneBefore != 1000)) {
        if ((FreeZoneAfter != 1000) && (FreeZoneBefore != 1000)) {
            g_AGO2_MEM_FreeZones[FreeZoneBefore].pEnd = g_AGO2_MEM_FreeZones[FreeZoneAfter].pEnd;
            g_AGO2_MEM_FreeZones[FreeZoneBefore].Size = g_AGO2_MEM_FreeZones[FreeZoneBefore].pEnd - g_AGO2_MEM_FreeZones[FreeZoneBefore].pStart;
            for (j = FreeZoneAfter + 1; j < g_AGO2_MEM_NumberOfFreeZones; j++) {
                g_AGO2_MEM_FreeZones[j-1].pStart = g_AGO2_MEM_FreeZones[j].pStart;
                g_AGO2_MEM_FreeZones[j-1].pEnd = g_AGO2_MEM_FreeZones[j].pEnd;
                g_AGO2_MEM_FreeZones[j-1].Size = g_AGO2_MEM_FreeZones[j].Size;
            }
            g_AGO2_MEM_NumberOfFreeZones--;
        }
        else if (FreeZoneAfter != 1000) {
            g_AGO2_MEM_FreeZones[FreeZoneAfter].pStart = (int)pBlock;
            g_AGO2_MEM_FreeZones[FreeZoneAfter].Size += pCurrentDescriptor->Size;
        }
        else if (FreeZoneBefore != 1000) {
            g_AGO2_MEM_FreeZones[FreeZoneBefore].pEnd = (int)pEnd;
            g_AGO2_MEM_FreeZones[FreeZoneBefore].Size += pCurrentDescriptor->Size;
        }
    }
    else {
        g_AGO2_MEM_FreeZones[g_AGO2_MEM_NumberOfFreeZones].pStart = (int)pBlock;
        g_AGO2_MEM_FreeZones[g_AGO2_MEM_NumberOfFreeZones].pEnd = (int)pEnd;
        g_AGO2_MEM_FreeZones[g_AGO2_MEM_NumberOfFreeZones].Size = pCurrentDescriptor->Size;
        g_AGO2_MEM_NumberOfFreeZones++;
        if (g_AGO2_MEM_NumberOfFreeZones == 1000) {
            AGO2_MEM_Shrink();
        }
    }

    for (j = HandleDescIndex + 1; j < g_AGO2_MEM_NbOfAllocatedBlocs; j++) {
        g_AGO2_MEM_HandleDescriptors[j-1].Handle = g_AGO2_MEM_HandleDescriptors[j].Handle;
        g_AGO2_MEM_HandleDescriptors[j-1].Size = g_AGO2_MEM_HandleDescriptors[j].Size;
        g_AGO2_MEM_HandleDescriptors[j-1].Pointer = g_AGO2_MEM_HandleDescriptors[j].Pointer;
    }
    g_AGO2_MEM_NbOfAllocatedBlocs--;
}

