void J_GetParticleSpriteFromInterpolatedPoints(J_ParticleSprite_* p, J_InterpolPoint_* p1, J_InterpolPoint_* p2, float V)
{
    float vA[4];
    unsigned int index;
    float fSum;
    float* pNoise;
    float* pW;
    float* pCol1;
    float* pCol2;
    float* pDstCol;

    vA[1] = (V - p1->UVs[1]) / (p2->UVs[1] - p1->UVs[1]);

    fSum = p1->UVs[0] * 1.5564321f + V * 3.4659879f;
    index = (int)(1024.0f * fSum);
    index = ((index & 0x7FF) + 3) & ~3u;

    vA[0] = 1.0f - vA[1];

    if (J_M_xAbs(vA[0]) < 0.0000001f || J_M_xAbs(vA[1]) < 0.0000001f)
        p->Flags = 1;
    else
        p->Flags = 0;

    pNoise = J_g_pNoiseTable + index;
    pCol1 = &p1->Color[0];
    pCol2 = &p2->Color[0];
    pW = &vA[0];
    pDstCol = &p->Color[0];

    asm {
        vsubx.w vf12, vf0, vf0x
        lqc2 vf1, 0(pNoise)
        lqc2 vf2, 0(p1)
        lqc2 vf3, 0(p2)
        lqc2 vf6, 0(pW)
        vsubz.z vf1, vf1, vf1z
        lqc2 vf4, 0(pCol1)
        lqc2 vf5, 0(pCol2)
        vmulx.xy vf1, vf1, vf25x
        vmulx.xyz vf8, vf2, vf6x
        vmuly.xyz vf9, vf3, vf6y
        vadd.xyz vf12, vf8, vf9
        vmulx.xyzw vf10, vf4, vf6x
        vmuly.xyzw vf11, vf5, vf6y
        vadd.xyz vf12, vf12, vf1
        vadd.xyzw vf13, vf10, vf11
        sqc2 vf12, 0(p)
        sqc2 vf13, 0(pDstCol)
    }
}

void fn_vPlaySubEventsSinceLastOneNoLoop(HIE_tdstSuperObject_* _hCharacter, tdstSubAnimInUse_* hNewSubAnimInUse)
{
    tdstEvent_* p_stEvent;
    unsigned char ucNumberOfEvents;
    float xFrame;

    p_stEvent = fn_p_GetEventsAddress(hNewSubAnimInUse->p_stTheSubAnim->p_stSubAnim, 0, 0);
    if (p_stEvent != NULL)
    {
        ucNumberOfEvents = hNewSubAnimInUse->p_stTheSubAnim->p_stSubAnim->ucNumberOfEvents;
        while ((unsigned char)hNewSubAnimInUse->ucNextEvent != ucNumberOfEvents)
        {
            if ((short)p_stEvent[hNewSubAnimInUse->ucNextEvent].uwFrameNumber >= 0)
                xFrame = (float)p_stEvent[hNewSubAnimInUse->ucNextEvent].uwFrameNumber;
            else
                xFrame = (float)((short)p_stEvent[hNewSubAnimInUse->ucNextEvent].uwFrameNumber >> 1);
            if (xFrame + xFrame > hNewSubAnimInUse->xFrameNumber)
                break;
            if (hNewSubAnimInUse->d_ucEventActivation[hNewSubAnimInUse->ucNextEvent] == 0)
            {
                fn_vPlayEvent(&p_stEvent[hNewSubAnimInUse->ucNextEvent], 0, _hCharacter);
                hNewSubAnimInUse->d_ucEventActivation[hNewSubAnimInUse->ucNextEvent] = p_stEvent[hNewSubAnimInUse->ucNextEvent].p_stfEventInTBL->ucPeriod;
            }
            else if (hNewSubAnimInUse->d_ucEventActivation[hNewSubAnimInUse->ucNextEvent] != 0xFF)
            {
                hNewSubAnimInUse->d_ucEventActivation[hNewSubAnimInUse->ucNextEvent] = hNewSubAnimInUse->d_ucEventActivation[hNewSubAnimInUse->ucNextEvent] - 1;
            }
            hNewSubAnimInUse->ucNextEvent = (signed char)(hNewSubAnimInUse->ucNextEvent + 1);
        }
    }
}

void MEC_fn_vProposeSpeed(DNM_stDynamics* p_stDynamic, float xDT, MAT_tdstTransformation_* hMatrix, MAT_tdstTransformation_* hInvMatrix)
{
    MAT_tdstTransformation_* hCurrentMatrix;
    MTH3D_tdstVector_ stTranslation;
    MTH3D_tdstVector_ stPosition;
    MTH3D_tdstVector_* pstProposeSpeed;
    MTH3D_tdstVector_* p_stPreviousPosition;
    float xSpeedX;
    float xSpeedY;
    float xSpeedZ;
    unsigned int ulEndFlags;
    unsigned int ulRotateFlag;

    hCurrentMatrix = &p_stDynamic->m_tdstDynamicsBaseBlock.m_stCurrentMatrix;
    pstProposeSpeed = &p_stDynamic->m_tdstDynamicsBaseBlock.m_stProposeSpeed;
    p_stPreviousPosition = (MTH3D_tdstVector_*)&p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3;
    ulRotateFlag = 0x8000;
    xSpeedX = xDT * p_stDynamic->m_tdstDynamicsBaseBlock.m_stProposeSpeed.xX;
    xSpeedY = xDT * p_stDynamic->m_tdstDynamicsBaseBlock.m_stProposeSpeed.xY;
    xSpeedZ = xDT * p_stDynamic->m_tdstDynamicsBaseBlock.m_stProposeSpeed.xZ;
    stTranslation.xX = hCurrentMatrix->stTransformMatrix.stCol_3.xX - p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3.xX;
    stTranslation.xY = hCurrentMatrix->stTransformMatrix.stCol_3.xY - p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3.xY;
    stTranslation.xZ = hCurrentMatrix->stTransformMatrix.stCol_3.xZ - p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3.xZ;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & ulRotateFlag) ? 0 : 1)
    {
        if ((0.0f == stTranslation.xX) && (0.0f == stTranslation.xY) && (0.0f != stTranslation.xZ))
        {
            if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags & 0x800) ? 1 : 0)
            {
                MAT_fn_vInvert(hInvMatrix, hMatrix);
                p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags &= 0xFFFFF7FF;
                p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags &= 0xFFFFF7FF;
            }
            MAT_fn_vRotateVector(&stTranslation, hInvMatrix, &stTranslation);
        }
    }
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x10) ? 1 : 0) stTranslation.xX = xSpeedX;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x20) ? 1 : 0) stTranslation.xY = xSpeedY;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x40) ? 1 : 0) stTranslation.xZ = xSpeedZ;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & ulRotateFlag) ? 0 : 1)
    {
        if ((0.0f == stTranslation.xX) && (0.0f == stTranslation.xY) && (0.0f != stTranslation.xZ))
        {
            MAT_fn_vRotateVector(&stTranslation, hMatrix, &stTranslation);
        }
    }
    stPosition.xX = p_stPreviousPosition->xX + stTranslation.xX;
    stPosition.xY = p_stPreviousPosition->xY + stTranslation.xY;
    stPosition.xZ = p_stPreviousPosition->xZ + stTranslation.xZ;
    if (hCurrentMatrix->eType == MAT_eTransform_Identity) hCurrentMatrix->eType = MAT_eTransform_Translation;
    *(int*)&hCurrentMatrix->stTransformMatrix.stCol_3.xX = *(int*)&stPosition.xX;
    *(int*)&hCurrentMatrix->stTransformMatrix.stCol_3.xY = *(int*)&stPosition.xY;
    *(int*)&hCurrentMatrix->stTransformMatrix.stCol_3.xZ = *(int*)&stPosition.xZ;
    hCurrentMatrix->stTransformMatrix.stCol_3.xW = 1.0f;
}

void MEC_fn_vImposeSpeed(DNM_stDynamics* p_stDynamic, float xDT, MAT_tdstTransformation_* hMatrix, MAT_tdstTransformation_* hInvMatrix)
{
    MTH3D_tdstVector_* pstImposeSpeed;
    MTH3D_tdstVector_ stTranslation;
    MTH3D_tdstVector_ stPosition;
    MAT_tdstTransformation_* hCurrentMatrix;
    MTH3D_tdstVector_* p_stPreviousPosition;
    float xSpeedX;
    float xSpeedY;
    float xSpeedZ;
    unsigned int ulEndFlags;

    hCurrentMatrix = &p_stDynamic->m_tdstDynamicsBaseBlock.m_stCurrentMatrix;
    pstImposeSpeed = &p_stDynamic->m_tdstDynamicsBaseBlock.m_stImposeSpeed;
    p_stPreviousPosition = (MTH3D_tdstVector_*)&p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3;
    xSpeedX = xDT * p_stDynamic->m_tdstDynamicsBaseBlock.m_stImposeSpeed.xX;
    xSpeedY = xDT * p_stDynamic->m_tdstDynamicsBaseBlock.m_stImposeSpeed.xY;
    xSpeedZ = xDT * p_stDynamic->m_tdstDynamicsBaseBlock.m_stImposeSpeed.xZ;
    stTranslation.xX = hCurrentMatrix->stTransformMatrix.stCol_3.xX - p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3.xX;
    stTranslation.xY = hCurrentMatrix->stTransformMatrix.stCol_3.xY - p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3.xY;
    stTranslation.xZ = hCurrentMatrix->stTransformMatrix.stCol_3.xZ - p_stDynamic->m_tdstDynamicsBaseBlock.m_stPreviousMatrix.stTransformMatrix.stCol_3.xZ;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x4000) ? 0 : 1)
    {
        if ((0.0f == stTranslation.xX) && (0.0f == stTranslation.xY) && (0.0f != stTranslation.xZ))
        {
            if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags & 0x800) ? 1 : 0)
            {
                MAT_fn_vInvert(hInvMatrix, hMatrix);
                ulEndFlags = p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags & 0xFFFFF7FF;
                p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags = ulEndFlags;
                p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags = ulEndFlags;
            }
            MAT_fn_vRotateVector(&stTranslation, hInvMatrix, &stTranslation);
        }
    }
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x20000) ? 1 : 0) stTranslation.xX = xSpeedX;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x40000) ? 1 : 0) stTranslation.xY = xSpeedY;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x80000) ? 1 : 0) stTranslation.xZ = xSpeedZ;
    if ((p_stDynamic->m_tdstDynamicsBaseBlock.ulFlags & 0x4000) ? 0 : 1)
    {
        if ((0.0f == stTranslation.xX) && (0.0f == stTranslation.xY) && (0.0f != stTranslation.xZ))
        {
            MAT_fn_vRotateVector(&stTranslation, hMatrix, &stTranslation);
        }
    }
    stPosition.xX = p_stPreviousPosition->xX + stTranslation.xX;
    stPosition.xY = p_stPreviousPosition->xY + stTranslation.xY;
    stPosition.xZ = p_stPreviousPosition->xZ + stTranslation.xZ;
    if (hCurrentMatrix->eType == MAT_eTransform_Identity) hCurrentMatrix->eType = MAT_eTransform_Translation;
    *(int*)&hCurrentMatrix->stTransformMatrix.stCol_3.xX = *(int*)&stPosition.xX;
    *(int*)&hCurrentMatrix->stTransformMatrix.stCol_3.xY = *(int*)&stPosition.xY;
    *(int*)&hCurrentMatrix->stTransformMatrix.stCol_3.xZ = *(int*)&stPosition.xZ;
    hCurrentMatrix->stTransformMatrix.stCol_3.xW = 1.0f;
}

void fn_vKillAllAlwaysInNonActiveSectors(void)
{
    tdstEngineObject_* p_stAlwaysEngObj;
    HIE_tdstSuperObject_** p_hGenerator;
    HIE_tdstSuperObject_** p_hLastGenerator;
    HIE_tdstSuperObject_* hAlwaysSuperObject;

    hAlwaysSuperObject = g_stAlways.d_stAlwaysSuperObject;
    p_hGenerator = g_stAlways.d_hAlwaysGenerator;
    p_hLastGenerator = p_hGenerator + g_stAlways.ulMaxNumberOfAlways;
    while (p_hGenerator < p_hLastGenerator)
    {
        p_stAlwaysEngObj = hAlwaysSuperObject->hLinkedObject.p_stCharacter;
        if (p_stAlwaysEngObj->h_StandardGame != NULL && p_stAlwaysEngObj->h_StandardGame->otObjectFamilyType != -1)
        {
            if (p_stAlwaysEngObj->h_StandardGame->eInitFlagWhenOutOfZone != 7 || ((((*p_hGenerator)->hLinkedObject.p_stCharacter->h_StandardGame->ucMiscFlags & 4)) != 0))
            {
                if (p_stAlwaysEngObj->h_StandardGame->ulCustomBits & 0x20000)
                {
                    if (PLA_fn_bTestIfEndOfAction(hAlwaysSuperObject))
                    {
                        fn_vKillEngineObjectOrAlwaysByPointer(p_stAlwaysEngObj);
                    }
                }
            }
            else
            {
                fn_vKillEngineObjectOrAlwaysByPointer(p_stAlwaysEngObj);
            }
        }
        if (*p_hGenerator == NULL)
        {
            hAlwaysSuperObject->hNextBrotherDyn = NULL;
        }
        p_hGenerator++;
        hAlwaysSuperObject++;
    }
}

