unsigned int J_CreateParticlesOnFace(J_ParticleSprite_* pGeneratedSprites, unsigned int MaxParticles, J_ParticleFace_* pFace, float _fU, float _fV, float NoiseLevel)
{
    int Edge[3];
    int NbEdges;
    float Noise[4];
    float InvfV;
    float InvfU;
    float FaceNormal[4];
    unsigned char bFirst;
    unsigned int NbGenerated;
    float V;
    float FirstV;
    float LastV;
    float RealMaxV;
    float RealMinV;
    float MaxV;
    float MinV;
    J_InterpolPoint_* pt1;
    J_InterpolPoint_* pt2;
    J_InterpolPoint_ p1;
    J_InterpolPoint_ p2;
    float RealMaxU;
    float RealMinU;
    float U;
    float LastU;
    float FirstU;
    float MaxU;
    float MinU;
    unsigned int i;
    int nNoise;
    float* pP0;
    float* pP1;
    float* pP2;
    float* pNormal;
    float* pSpriteNormal;
    int bOnEdge;

    bFirst = 1;
    NbGenerated = 0;
    InvfU = 1.0f / _fU;
    InvfV = 1.0f / _fV;

    if (J_g_pNoiseTable == NULL)
    {
        J_g_pNoiseTable = (float*)malloc(0x2010);
        nNoise = 0;
        do
        {
            nNoise++;
            J_g_pNoiseTable[nNoise - 1] = 10.0f * ((float)rand() / 2147483648.0f) - 5.0f;
        } while (nNoise < 0x804);
    }

    /* VU0 face normal: normalize((p1 - p0) x (p2 - p1)). */
    pP0 = &pFace->pPoints[0][0];
    pP1 = &pFace->pPoints[1][0];
    pP2 = &pFace->pPoints[2][0];
    pNormal = &FaceNormal[0];
    asm {
        lqc2 vf1, 0(pP0)
        lqc2 vf2, 0(pP1)
        lqc2 vf3, 0(pP2)
        vsub.xyz vf4, vf2, vf1
        vsub.xyz vf5, vf3, vf2
        vsub.xyzw vf26, vf0, vf0
        vopmula.xyz ACC, vf4, vf5
        vopmsub.xyz vf6, vf5, vf4
        vmul.xyz vf7, vf6, vf6
        vaddy.x vf7, vf7, vf7y
        vaddz.x vf7, vf7, vf7z
        vrsqrt Q, vf0w, vf7x
        vwaitq
        vmulq.xyz vf26, vf6, Q
        sqc2 vf26, 0(pNormal)
    }

    J_g_NoiseLevel = NoiseLevel;
    Noise[0] = NoiseLevel;

    /* Smallest and largest U of the face. */
    MinU = pFace->pUVs[0][0];
    MaxU = MinU;
    for (i = 1; i < 3; i++)
    {
        float u = pFace->pUVs[i][0];
        if (u < MinU)
            MinU = u;
        if (u > MaxU)
            MaxU = u;
    }

    /* Snap the U range onto the particle grid. */
    RealMinU = MinU * InvfU;
    RealMinU = (float)(int)RealMinU;
    RealMinU = _fU * RealMinU;
    if (RealMinU < MinU)
        RealMinU += _fU;
    FirstU = RealMinU;
    while (FirstU + _fU <= MaxU)
        FirstU += _fU;
    RealMaxU = FirstU;

    if (RealMinU > MaxU)
        return 0;
    U = FirstU + 0.5f * _fU;
    if (U < MinU)
        return 0;

    RealMinV = 0.0f;
    while (RealMinU <= U)
    {
        if (NbGenerated < MaxParticles)
        {
            NbEdges = 0;
            bOnEdge = (((RealMinU >= pFace->pUVs[0][0]) && (RealMinU <= pFace->pUVs[0][1]))
                       || ((RealMinU >= pFace->pUVs[0][1]) && (RealMinU <= pFace->pUVs[0][0])));
            if (bOnEdge)
            {
                Edge[NbEdges] = 0;
                NbEdges++;
            }
            bOnEdge = (((RealMinU >= pFace->pUVs[0][1]) && (RealMinU <= pFace->pUVs[1][0]))
                       || ((RealMinU >= pFace->pUVs[1][0]) && (RealMinU <= pFace->pUVs[0][1])));
            if (bOnEdge)
            {
                Edge[NbEdges] = 1;
                NbEdges++;
            }
            bOnEdge = (((RealMinU >= pFace->pUVs[1][0]) && (RealMinU <= pFace->pUVs[0][0]))
                       || ((RealMinU >= pFace->pUVs[0][0]) && (RealMinU <= pFace->pUVs[1][0])));
            if (bOnEdge)
            {
                Edge[NbEdges] = 2;
                NbEdges++;
            }

            if (NbEdges == 2)
            {
                J_GetInterpolPointOnEdge(pFace, &p1, Edge[0], RealMinU);
                J_GetInterpolPointOnEdge(pFace, &p2, Edge[1], RealMinU);
                if (p1.UVs[1] < p2.UVs[1])
                {
                    pt1 = &p1;
                    pt2 = &p2;
                }
                else
                {
                    pt1 = &p2;
                    pt2 = &p1;
                }
                MinV = pt1->UVs[1];
                MaxV = pt2->UVs[1];
                RealMinV = MinV * InvfV;
                RealMinV = (float)(int)RealMinV;
                RealMinV = _fV * RealMinV;
                if (RealMinV < MinV)
                    RealMinV += _fV;
                FirstV = RealMinV;
                while (FirstV + _fV <= MaxV)
                    FirstV += _fV;
                RealMaxV = FirstV;
                if (RealMinV <= MaxV)
                {
                    V = FirstV + 0.5f * _fV;
                    if (V >= MinV)
                    {
                        while ((V <= V) && (NbGenerated < MaxParticles))
                        {
                            pSpriteNormal = &pGeneratedSprites[NbGenerated].FaceNormal[0];
                            pGeneratedSprites[NbGenerated].bFirst = bFirst;
                            asm {
                                sqc2 vf26, 0(pSpriteNormal)
                            }
                            J_GetParticleSpriteFromInterpolatedPoints(&pGeneratedSprites[NbGenerated], pt1, pt2, V);
                            NbGenerated++;
                            bFirst = 0;
                            V += _fV;
                        }
                    }
                }
            }
        }
        RealMinU += _fU;
    }
    return NbGenerated;
}

extern "C" void usnd_vEnterCritSect(unsigned int uiCS)
{
    unsigned int uiThreadId;

    uiThreadId = GetThreadId();
    if (gs_uiCSThread[uiCS - 1] == uiThreadId)
    {
        gs_uiCSCount[uiCS - 1]++;
    }
    else
    {
        WaitSema(uiCS - 1);
        gs_uiCSThread[uiCS - 1] = uiThreadId;
        gs_uiCSCount[uiCS - 1] = 1;
    }
}

extern "C" void usnd_vKillTimer(unsigned int uiTimerId)
{
    _usnd_STimerStruct* pToBeKilled;
    unsigned int uiThreadId;
    unsigned int uiCS;

    pToBeKilled = (_usnd_STimerStruct*)uiTimerId;
    if (uiTimerId == 0)
    {
        return;
    }
    uiThreadId = GetThreadId();
    uiCS = g_uiCritSect;
    if (gs_uiCSThread[uiCS - 1] == uiThreadId)
    {
        gs_uiCSCount[uiCS - 1]++;
    }
    else
    {
        WaitSema(uiCS - 1);
        gs_uiCSThread[uiCS - 1] = uiThreadId;
        gs_uiCSCount[uiCS - 1] = 1;
    }
    pToBeKilled->m_bDelete = 1;
    SignalSema(g_uiTimerSem);
    gs_uiCSCount[g_uiCritSect - 1]--;
    if (gs_uiCSCount[g_uiCritSect - 1] == 0)
    {
        gs_uiCSThread[g_uiCritSect - 1] = (unsigned int)-1;
        SignalSema(g_uiCritSect - 1);
    }
}

extern "C" unsigned int usnd_uiSetTimer(unsigned int uiDelay, void* pTimer, void (*pfnCallback)(unsigned int, unsigned int), unsigned int uiUserParam)
{
    _usnd_STimerStruct* pSTS;
    unsigned int uiThreadId;
    unsigned int uiCS;

    pSTS = NULL;
    if (uiDelay != 0)
    {
        pSTS = (_usnd_STimerStruct*)usnd_malloc(0x20);
    }
    if (pSTS == NULL)
    {
        return 0;
    }
    pSTS->m_pfnCallback = pfnCallback;
    pSTS->m_uiUserParam = uiUserParam;
    pSTS->m_uiPeriod = (unsigned int)(((unsigned long long)uiDelay * 2500 * 0x10624DD3) >> 38);
    pSTS->m_uiTime = usnd_guiTickT0 + pSTS->m_uiPeriod;
    pSTS->m_bDelete = 0;
    pSTS->m_bCall = 0;
    uiThreadId = GetThreadId();
    uiCS = g_uiCritSect;
    if (gs_uiCSThread[uiCS - 1] == uiThreadId)
    {
        gs_uiCSCount[uiCS - 1]++;
    }
    else
    {
        WaitSema(uiCS - 1);
        gs_uiCSThread[uiCS - 1] = uiThreadId;
        gs_uiCSCount[uiCS - 1] = 1;
    }
    pSTS->m_next = (_usnd_STimerStruct*)g_sTimers;
    g_sTimers = (int)pSTS;
    gs_uiCSCount[g_uiCritSect - 1]--;
    if (gs_uiCSCount[g_uiCritSect - 1] == 0)
    {
        gs_uiCSThread[g_uiCritSect - 1] = (unsigned int)-1;
        SignalSema(g_uiCritSect - 1);
    }
    return (unsigned int)pSTS;
}

