        for (i = 0; i < 3; i++, pDstBB += 2)
        {
            if (pDstBB[0] > pSrcBB[0])
                pDstBB[0] = pSrcBB[0];
            if (pDstBB[1] < pSrcBB[1])
                pDstBB[1] = pSrcBB[1];
            pSrcBB += 2;
