           keeping them together reproduces its DWARF line entries. */
        pDstBB[1] = -16777215.0f; pDstBB[2] = 16777215.0f; pDstBB[3] = -16777215.0f; pDstBB[4] = 16777215.0f; pDstBB[5] = -16777215.0f;
