void MEC_fn_vTranslateMatrixOn(DNM_stDynamics* p_stDynamic, MTH3D_tdstVector_* p_stMatrixTranslation)
{
    MAT_tdstTransformation_* hCurrentMatrix;
    MAT_tdstTransformation_* hPreviousMatrix;

