        MAT_tdstTransformation_* hGlobalMatrix;
        MAT_fn_vCompose(_hSprObj->hGlobalMatrix, HIE_g_a_hMatrixStack[HIE_g_lNbMatrixInStack], _hSprObj->hLocalMatrix);
