tdstNodeInterpret_* fn_p_stBooleanCondition(HIE_tdstSuperObject_* p_SuperObjPerso, tdstNodeInterpret_* p_stTree, int* p_lValue)
{
    int l1;
    tdstNodeInterpret_* p_stTreeInit;
    tdeCondId_ eCondId;
    tdstGetSetParam_ stValue;

    eCondId = p_stTree[-1].uDummy.uId.eCondId;
    p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stValue);
    *p_lValue = stValue.uDummy.uParam.lValue;
    switch (eCondId) {
    case 0:
        if (*p_lValue == 0) {
            if (p_stTree->uwNodeToSkip) {
                p_stTreeInit = p_stTree;
                p_stTree = (tdstNodeInterpret_*)(p_stTree->uwNodeToSkip * sizeof(tdstNodeInterpret_) + (char*)p_stTree);
            } else {
                p_stTreeInit = p_stTree;
                p_stTree = fn_p_stSwapNextParameter(p_stTree);
                p_stTreeInit->uwNodeToSkip = (unsigned short)(p_stTree - p_stTreeInit);
            }
        } else {
            p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stValue);
            *p_lValue = stValue.uDummy.uParam.lValue;
        }
        break;
    case 1:
        if (*p_lValue != 0) {
            if (p_stTree->uwNodeToSkip) {
                p_stTreeInit = p_stTree;
                p_stTree = (tdstNodeInterpret_*)(p_stTree->uwNodeToSkip * sizeof(tdstNodeInterpret_) + (char*)p_stTree);
            } else {
                p_stTreeInit = p_stTree;
                p_stTree = fn_p_stSwapNextParameter(p_stTree);
                p_stTreeInit->uwNodeToSkip = (unsigned short)(p_stTree - p_stTreeInit);
            }
        } else {
            p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stValue);
            *p_lValue = stValue.uDummy.uParam.lValue;
        }
        break;
    case 2:
        *p_lValue = (*p_lValue == 0) ? 1 : 0;
        break;
    case 3:
        l1 = *p_lValue;
        p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stValue);
        *p_lValue = (l1 ^ *p_lValue) ? 1 : 0;
        break;
    default:
        *p_lValue = 0;
        break;
    }
    return p_stTree;
}

unsigned char IPT_fn_bIsKeyWordValid_JoystickJustReleased(IPT_tdstKeyWordElement_* _hKeyWordElement)
{
    stDevice* hPad;
    unsigned char ucReturn = 0;
    short swKeyWord;
    unsigned int ulMask;

    IPT_g_hNextParameter = (int)(_hKeyWordElement + 1);
    swKeyWord = ((IPT_tdstKeyWordElement_*)IPT_g_hNextParameter)->u_ElementUnion.swKeyWord;
    hPad = IPT_g_hInputStructure.a_stDevice[swKeyWord + 2].hDeviceHandle;
    IPT_g_hNextParameter = (int)((IPT_tdstKeyWordElement_*)IPT_g_hNextParameter + 1);
    if (IPT_g_hInputStructure.a_stDevice[swKeyWord + 2].ucValideAndActiveDevice == 2)
    {
        swKeyWord = ((IPT_tdstKeyWordElement_*)IPT_g_hNextParameter)->u_ElementUnion.swKeyWord;
        if (swKeyWord >= 0x1C && swKeyWord <= 0x2B)
        {
            ulMask = IPT_g_ulPadAndJoyButtonFlag[swKeyWord - 28];
            ucReturn = ((ulMask & *(unsigned int*)((char*)hPad->m_p_stState + 4)) == ulMask) ||
                       ((ulMask & INO_fn_ulJoyPreviousButtons(hPad)) == ulMask);
        }
    }
    IPT_g_hNextParameter += 12;
    return ucReturn;
}

