void TFMT_vUpdateScaleTable(char* szText)
{
    char* szCur;
    int i;

    szCur = strtok(szText, ":");
    TFMT_ga_fLetterScale[0] = (float)atol(szCur) / 1000.0f;
    i = 1;
    while (szCur != NULL && i < 256)
    {
        szCur = strtok(NULL, ":");
        if (szCur == NULL)
            break;
        TFMT_ga_fLetterScale[i] = (float)atol(szCur) / 1000.0f;
        i++;
        szCur[-1] = ':';
    }
    TFMT_ga_ulNbScale = i;
}

void TFMT_vUpdateSpacingTable(char* szText)
{
    char* szCur;
