            *p_xT = 0.0f;
            *p_stHit = *p_stVertexA;
            return 1;
        }
    }
    if (xDivid >= 0.0f)
    {
        if (xDivid < -xDotProduct)
        {
            xDivid = xDivid / xDotProduct;
            xDivid = -xDivid;

            p_stHit->xX = p_stVertexA->xX + xDivid * p_stVectAB->xX;
