    GLI_vRestoreSavedFrameBuffer();
    MC_DrawString(MC_Strings[0], 450.0f);
    MC_SwapBuffers();
    MC_DrawString(MC_Strings[0], 450.0f);
    MC_SwapBuffers();
    MC_WaitForXButtonRelease();
    do
    {
        GLI_vRestoreSavedFrameBuffer();
        MC_DrawString(MC_Strings[0], 450.0f);
        MC_SwapBuffers();
