    else if (g_CurrentMenu2DPage == g_AlbumPage)
    {
        switch (PS2MC_fn_iGetFunctionResult(3))
        {
        case 1:
            i = (int)PS2MC_g_NbFilesFound;
            if (PS2MC_g_NbFilesFound >= 4)
            {
                i = 3;
            }
