void GLI_PS2GL_PrepareSpecificDataForSPO(HIE_tdstSuperObject_* _hSO)
{
    SECT_tdstSector_* hSectorObject;
    int i;
    GEO_tdstVisualSet_* hVisualSet;
    tdstObjectsTablesList_* p_stObjectTable;
    tdstObjectsTableElement_* p_ObjectsTableElement;
    PO_tdstPhysicalObject_* PO;
    IPO_tdstInstanciatedPhysicalObject_* hIPO;
    HIE_tdstSuperObject_* hChild;
    tdstEngineObject_* p_stCharacter;
    tdst3dData_* p_st3dData;
    short iNbElement;
    int iNbLod;

    if (_hSO != NULL) {
        iNbElement = 0;
        hChild = _hSO->hFirstElementDyn;
        if (hChild != NULL) {
            do {
                GLI_PS2GL_PrepareSpecificDataForSPO(hChild);
                hChild = hChild->hNextBrotherDyn;
                iNbElement++;
            } while (hChild != NULL);
        }
    }
    if (_hSO->ulTypeOfLinkedObject == 2) {
        if (_hSO != NULL) {
            p_stCharacter = _hSO->hLinkedObject.p_stCharacter;
            if (p_stCharacter != NULL) {
                p_st3dData = p_stCharacter->h_3dData;
                if (p_st3dData != NULL) {
                    p_stObjectTable = p_st3dData->h_CurrentObjectsTable;
                    if (p_stObjectTable != NULL) {
                        iNbElement = 0;
                        if (p_stObjectTable->wNumberOfElement != 0) {
                            p_ObjectsTableElement = p_stObjectTable->d_stObjectsTable;
                            for (; iNbElement < p_stObjectTable->wNumberOfElement; iNbElement++) {
                                if (p_ObjectsTableElement->wTypeOfTarget == 0) {
                                    hVisualSet = PO_fn_hGetVisualSet((PO_tdstPhysicalObject_*)p_ObjectsTableElement->h_Target);
                                    if (hVisualSet != NULL) {
                                        if (hVisualSet->xType == 0) {
                                            if (hVisualSet->xNbLodDefinitions == 0) {
                                                GLI_vInspectObjectForShadow(hVisualSet->d_p_stLodDefinitions[0].p_stGeometricObject);
                                            } else {
                                                for (iNbLod = 0; iNbLod < hVisualSet->xNbLodDefinitions; iNbLod++) {
                                                    GLI_vInspectObjectForShadow(hVisualSet->d_p_stLodDefinitions[iNbLod].p_stGeometricObject);
                                                }
                                            }
                                        }
                                    }
                                }
                                p_ObjectsTableElement++;
                            }
                        }
                    }
                }
            }
        }
    }
    else if (_hSO->ulTypeOfLinkedObject == 4) {
        hSectorObject = _hSO->hLinkedObject.p_stSector;
        if (hSectorObject != NULL) {
            hSectorObject->glOpaqueDisplayList = 0;
            hSectorObject->glTransparentDisplayList = 0;
        }
    }
    else if (_hSO->ulTypeOfLinkedObject == 32) {
        hIPO = _hSO->hLinkedObject.p_stInstanciatedPhysicalObject;
        if (hIPO != NULL) {
            PO = hIPO->_hPhysicalObject;
            if (PO != NULL) {
                GLI_PS2GL_BuildSpecifForPO(PO);
            }
        }
    }
    else if (_hSO->ulTypeOfLinkedObject == 8) {
        PO = _hSO->hLinkedObject.p_stPhysicalObject;
        if (PO != NULL) {
            GLI_PS2GL_BuildSpecifForPO(PO);
        }
    }
}

short INO_fn_wReadAllDevices(unsigned short _uwType, short _wMode)
{
    short wReadResult;
    stDevice** p_hDevice;
    short xIndex;
    short wResult;
    short wOneGood;
    stDevice* hDev;

    wOneGood = -1;
    wResult = 1;

    if (!(INO_gs_ucINOInitOK ? 1 : 0))
    {
        return wOneGood;
    }

    for (xIndex = INO_gs_xNbDevice - 1, p_hDevice = (stDevice**)&INO_gs_a_tdhDevice[xIndex]; xIndex >= 0; xIndex--, p_hDevice--)
    {
        INO_fn_wIsConnectedFast(*p_hDevice);
    }

    for (xIndex = INO_gs_xNbDevice - 1, p_hDevice = (stDevice**)&INO_gs_a_tdhDevice[xIndex]; xIndex >= 0; xIndex--, p_hDevice--)
    {
        hDev = *p_hDevice;
        if ((hDev->m_uwType & _uwType) && (hDev->m_p_stState->m_ucStatus & 2))
        {
            switch (_wMode)
            {
            case 1:
                if (hDev->m_uwType != 0x10)
                {
                    wReadResult = -1;
                }
                else
                {
                    wReadResult = INO_fn_wIsJoystickConnectedFast(hDev);
                }
                if (wReadResult == 1)
                {
                    hDev->m_p_stState->m_ucStatus |= 1;
                }
                else
                {
                    hDev->m_p_stState->m_ucStatus &= ~1;
                }
                /* fall through */
            case 2:
            default:
                if (hDev->m_p_stState->m_ucStatus & 1)
                {
                    if (hDev->m_pfnRead)
                    {
                        wReadResult = hDev->m_pfnRead(hDev);
                    }
                    else
                    {
                        wReadResult = -1;
                    }
                    wOneGood = 1;
                    if (wResult != -1)
                    {
                        if (wReadResult == -1)
                        {
                            wResult = -1;
                        }
                        else
                        {
                            wResult = wResult & wReadResult;
                        }
                    }
                }
                else
                {
                    hDev->m_p_stState->m_ucStatus &= ~1;
                }
                break;
            }
        }
    }

    if (wOneGood != -1)
    {
        return wResult;
    }
    if (_wMode == 1)
    {
        return wResult;
    }
    return INO_fn_wReadAllDevices(_uwType, 1);
}

short MOR_fn_xStopMorph(HIE_tdstSuperObject_* _hActorSuperObject, short _xChannelIndex)
{
    HIE_tdstSuperObject_* hSuperObject;
    MOR_stMorphStruct_* mp;
    PO_tdstPhysicalObject_* pMorphedPhysicalObject;
    PO_tdstPhysicalObject_* pEndPhysicalObject;
    HIE_tdstSuperObject_* hChildSuperObject;
    unsigned short uwChannelNumber;
    short j;
    short xMorphListIndex;

    uwChannelNumber = (unsigned short)_xChannelIndex;
    xMorphListIndex = fn_hMorphListIndex(((tdstEngineObject_*)_hActorSuperObject->hLinkedObject.p_stCharacter)->h_3dData->hMorphChannelList, _xChannelIndex);
    if (xMorphListIndex == -1 || !g_MorphTasksList[xMorphListIndex].bInUse)
        return -1;

    mp = NULL;
    for (j = 0; j < 50; j++)
    {
        mp = &g_MorphTasksList[j];
        if (mp->bInUse && mp->hActorSuperObject == _hActorSuperObject && mp->xChannelIndex == _xChannelIndex)
            break;
        mp = NULL;
    }
    if (mp == NULL)
        return -1;

    hSuperObject = mp->hActorSuperObject;
    pMorphedPhysicalObject = mp->pMorphedPhysicalObject;
    pEndPhysicalObject = *(PO_tdstPhysicalObject_**)(void*)((char*)&((tdstEngineObject_*)mp->hActorSuperObject->hLinkedObject.p_stCharacter)->h_3dData->h_CurrentObjectsTable->d_stObjectsTable[0].h_Target + mp->axEndIndexInObjectTable[0] * sizeof(tdstObjectsTableElement_));
    if (hSuperObject->hLinkedObject.p_stPhysicalObject == pMorphedPhysicalObject)
    {
        hSuperObject->ulTypeOfLinkedObject = (pEndPhysicalObject != NULL) ? 8 : 1;
        hSuperObject->hLinkedObject.p_stPhysicalObject = pEndPhysicalObject;
    }
    else
    {
        for (hChildSuperObject = hSuperObject->hFirstElementDyn; hChildSuperObject != NULL; hChildSuperObject = hChildSuperObject->hNextBrotherDyn)
        {
            if (MOR_fn_bRemoveMorphedObjectFromHierarchy(hChildSuperObject, pMorphedPhysicalObject, pEndPhysicalObject))
                break;
        }
    }

    fn_vPushAllocModeAccordingToObject(_hActorSuperObject);
    mp->bInUse = 0;
    fn_vRemoveChannelFromMorphList(((tdstEngineObject_*)_hActorSuperObject->hLinkedObject.p_stCharacter)->h_3dData->hMorphChannelList, uwChannelNumber);
    GAM_fn_vPopAllocMode();
    return 0;
}

int ReadDirInCache(stFile_* pLevel)
{
    int i;
    int last;
    stFile_* pNewFile;
    unsigned char* first;
    int numSectors;
    char work[16];
    int l;
    int j;
    int n;
    unsigned int uiSector;
    numSectors = (pLevel->length + 0x7FF) >> 11;
    pLevel->pChild = &ax_FileCache[g_NbCacheFiles];
    pLevel->nb_sons = 0;
    if (pLevel->length == 0) {
        return -1;
    }
    for (i = 0; i < numSectors; i++) {
        last = 0;
        uiSector = pLevel->sector;
        CDmode.trycount = 20;
        g_NbSectRead++;
        CDmode.spindlctrl = 0;
        CDmode.datapattern = 0;
        SearchSectorCache((unsigned long)(uiSector + i), loadbuf);
        for (first = loadbuf + last; first[0] != 0; first = loadbuf + last) {
            l = first[0x20];
            n = last + 0x21;
            j = 0;
            if (n <= last + 0x20 + l) {
                do {
                    work[j] = loadbuf[n];
                    n++;
                    j++;
                } while (n <= last + 0x20 + l);
            }
            work[j] = 0;
            pNewFile = &ax_FileCache[g_NbCacheFiles++];
            memset(pNewFile, 0, 32);
            strncpy(pNewFile->name, work, 16);
            pNewFile->name[15] = 0;
            pNewFile->sector = first[2] + (first[3] << 8) + (first[4] << 16) + (first[5] << 24);
            pNewFile->length = first[10] + (first[11] << 8) + (first[12] << 16) + (first[13] << 24);
            pLevel->nb_sons++;
            last += first[0];
        }
    }
    return 0;
}

void fn_vPreviousSelectionNoWrap(void)
{
    unsigned int u32Sound2Play;

    u32Sound2Play = 2;

    if (g_CurrentSelection == 0)
    {
        if (aMenu2DPages[g_CurrentMenu2DPage].NbSelection == aMenu2DPages[g_CurrentMenu2DPage].NbEntry)
        {
            u32Sound2Play = 10;
        }
        else
        {
            if (aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry == 0)
            {
                u32Sound2Play = 10;
            }
            else
            {
                aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry--;
            }
        }
    }
    else
    {
        g_CurrentSelection--;
    }

    fn_vPlaySoundInGameMenu2D(u32Sound2Play);

    if (aMenu2DPages[g_CurrentMenu2DPage].abGrayed[g_CurrentSelection] != 0)
    {
        u32Sound2Play = 2;

        if (g_CurrentSelection == 0)
        {
            if (aMenu2DPages[g_CurrentMenu2DPage].NbSelection == aMenu2DPages[g_CurrentMenu2DPage].NbEntry)
            {
                u32Sound2Play = 10;
            }
            else
            {
                if (aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry == 0)
                {
                    u32Sound2Play = 10;
                }
                else
                {
                    aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry--;
                    u32Sound2Play = 2;
                }
            }
        }
        else
        {
            g_CurrentSelection--;
            u32Sound2Play = 2;
        }

        fn_vPlaySoundInGameMenu2D(u32Sound2Play);

        if (aMenu2DPages[g_CurrentMenu2DPage].abGrayed[g_CurrentSelection] != 0)
        {
            fn_vPreviousSelectionNoWrap();
        }
    }
}

int fn_bTestSamePosition(tdstAnim3d_* p_stPreviousAnim, tdstAnim3d_* p_stNextAnim, unsigned short uwPreviousFrame, unsigned short uwNextFrame)
{
    tdstA3dGENERAL_* p_stPreviousA3dGeneral;
    tdstA3dGENERAL_* p_stNextA3dGeneral;
    tdstChannel_* p_stPreviousChannel;
    tdstChannel_* p_stCurrentChannel;
    tdstKeyFrame_* p_stOldKeyFrame;
    tdstKeyFrame_* p_stNewKeyFrame;
    tdstKeyFrame_* p_stPreviousKeyFrame;
    tdstKeyFrame_* p_stNextKeyFrame;
    tdstKeyFrame_* a256_p_stPrevKeyFrames[256];
    tdstKeyFrame_* a256_p_stNextKeyFrames[256];
    unsigned short uwCnt1;

    memset(a256_p_stPrevKeyFrames, 0, sizeof(a256_p_stPrevKeyFrames));
    memset(a256_p_stNextKeyFrames, 0, sizeof(a256_p_stNextKeyFrames));

    p_stPreviousA3dGeneral = fn_p_GetA3dGENERAL(p_stPreviousAnim->uwNumOfA3dGENERAL, uwPreviousFrame);
    p_stPreviousChannel = &gp_stChannels[p_stPreviousA3dGeneral->uwNumOfFirstChannel];
    for (uwCnt1 = 0; uwCnt1 < p_stPreviousA3dGeneral->uwNumberOfChannels; uwCnt1++)
    {
        if (p_stPreviousChannel->uwChannelNumber != 0xFFFF)
        {
            p_stOldKeyFrame = &gp_stKeyFrames[gp_FramesKFIndex[p_stPreviousChannel->ulNumOfFirstFrameKF + uwPreviousFrame]];
            if ((p_stOldKeyFrame->uwMask & 0x80) && (p_stOldKeyFrame->uwMask & 0x200))
                p_stOldKeyFrame = &gp_stKeyFrames[gp_FramesKFIndex[p_stPreviousChannel->ulNumOfFirstFrameKF]];
            a256_p_stPrevKeyFrames[uwCnt1] = p_stOldKeyFrame;
        }
        p_stPreviousChannel++;
    }

    p_stNextA3dGeneral = fn_p_GetA3dGENERAL(p_stNextAnim->uwNumOfA3dGENERAL, uwNextFrame);
    p_stCurrentChannel = &gp_stChannels[p_stNextA3dGeneral->uwNumOfFirstChannel];
    for (uwCnt1 = 0; uwCnt1 < p_stNextA3dGeneral->uwNumberOfChannels; uwCnt1++)
    {
        if (p_stCurrentChannel->uwChannelNumber != 0xFFFF)
        {
            p_stNewKeyFrame = &gp_stKeyFrames[gp_FramesKFIndex[p_stCurrentChannel->ulNumOfFirstFrameKF + uwNextFrame]];
            if ((p_stNewKeyFrame->uwMask & 0x80) && (p_stNewKeyFrame->uwMask & 0x200))
                p_stNewKeyFrame = &gp_stKeyFrames[gp_FramesKFIndex[p_stCurrentChannel->ulNumOfFirstFrameKF]];
            a256_p_stNextKeyFrames[uwCnt1] = p_stNewKeyFrame;
        }
        p_stCurrentChannel++;
    }

    for (uwCnt1 = 0; uwCnt1 < p_stPreviousA3dGeneral->uwNumberOfChannels; uwCnt1++)
    {
        p_stPreviousKeyFrame = a256_p_stPrevKeyFrames[uwCnt1];
        p_stNextKeyFrame = a256_p_stNextKeyFrames[uwCnt1];

        if (memcmp(&gp_a3_xVectors[a256_p_stPrevKeyFrames[uwCnt1]->uwNumOfPosition], &gp_a3_xVectors[a256_p_stNextKeyFrames[uwCnt1]->uwNumOfPosition], sizeof(MTH3D_tdstVector_)))
