void IPO_fn_vFrameInitForRLITables(void)
{
    unsigned int ulCurrentTime;
    int lDelta;
    float fDelta;

    if (IPO_g_cTransitionInProgress)
    {
        ulCurrentTime = g_stEngineStructure.stEngineTimer.ulCurrentTimerCount; lDelta = (int)(ulCurrentTime - IPO_g_ulCurrentTime); fDelta = lDelta >= 0 ? (float)lDelta : (float)((lDelta >> 1) | (lDelta & 1)) + (float)((lDelta >> 1) | (lDelta & 1)); IPO_g_fIncrementByMilliSecond = IPO_g_fCurrentIncrementRatio * fDelta;
        IPO_g_fPreviousGlobalRatio = IPO_g_fCurrentGlobalRatio;
        IPO_g_fCurrentGlobalRatio = IPO_g_fCurrentGlobalRatio + IPO_g_fIncrementByMilliSecond;
        if (IPO_g_cChangeMode == 1)
        {
            if (IPO_g_fCurrentGlobalRatio > 1.0f)
                IPO_g_fCurrentGlobalRatio = 1.0f;
        }
        else if (IPO_g_cChangeMode == 2)
        {
            if (IPO_g_fAddWantedRatio >= 0.0f)
            {
                if (IPO_g_fCurrentGlobalRatio > IPO_g_fAddWantedRatio)
                {
                    IPO_g_fCurrentGlobalRatio = IPO_g_fAddWantedRatio;
                }
            }
            else if (IPO_g_fAddWantedRatio <= 0.0f)
            {
                if (IPO_g_fCurrentGlobalRatio < IPO_g_fAddWantedRatio)
                {
                    IPO_g_fCurrentGlobalRatio = IPO_g_fAddWantedRatio;
                }
            }
        }
        else
        {
            IPO_g_cTransitionInProgress = 0;
        }
        IPO_g_ulCurrentTime = ulCurrentTime;
    }
}

void LS_FinallyIThinkIOnlyHaveThisSizeLeftToLoad(int SizeLeft)
{
    float Percent;
    Percent = 2.0f * (float)(g_ProgressSizeHaveRead / 2) / (2.0f * (float)(g_ProgressSizeToRead / 2));
    if (Percent > 0.99f)
        Percent = 0.99f;
    if (Percent < 0.01f)
        Percent = 0.01f;
    g_ProgressSizeToRead = (int)((float)SizeLeft / (1.0f - Percent));
    g_ProgressSizeHaveRead = g_ProgressSizeToRead - SizeLeft;
}

