            h_SO = fn_h_StandardGameGetSuperObject(p_stObject->h_StandardGame);
            fn_vSectInfoInitForSingleCharacter(h_SO, p_stPosition);
            *(int*)&p_stObject->h_SectInfo->stPreviousPosition.xX = *(int*)&p_stPosition->xX;
            *(int*)&p_stObject->h_SectInfo->stPreviousPosition.xY = *(int*)&p_stPosition->xY;
            *(int*)&p_stObject->h_SectInfo->stPreviousPosition.xZ = *(int*)&p_stPosition->xZ;
        }
        break;
    case OTI_AlwaysCreated:
        if (fn_h_StandardGameGetSuperObject(p_stObject->h_StandardGame))
        {
            p_stObject->h_SectInfo->hSectorSynchroCharacter = NULL;
            h_SO = fn_h_StandardGameGetSuperObject(p_stObject->h_StandardGame);
            p_stPosition = (MTH3D_tdstVector_*)&h_SO->hGlobalMatrix->stTransformMatrix.stCol_3;
            fn_vInsertObjectInSectorList(p_stObject->h_SectInfo->hCurrentSector, h_SO);
            SECT_fn_vSetCharacterPointerInCharacterList(p_stObject->h_SectInfo->hNodeInSector, h_SO);
            *(int*)&p_stObject->h_SectInfo->stPreviousPosition.xX = *(int*)&p_stPosition->xX;
            *(int*)&p_stObject->h_SectInfo->stPreviousPosition.xY = *(int*)&p_stPosition->xY;
            *(int*)&p_stObject->h_SectInfo->stPreviousPosition.xZ = *(int*)&p_stPosition->xZ;
            hLight = h_SO->hLinkedObject.p_stCharacter->h_MSLight;
            if (hLight)
                SECT_fn_vSetHandleOfLightsInDNMLightsList(fn_hMSLightGetLightNodeInSector(hLight), fn_p_stMSLightGetLight(hLight));
        }
        break;
    }

    GAM_fn_vPopAllocMode();
}

void GAM_fn_vSectInfoTestChangeSectorForCharacter(HIE_tdstSuperObject_* _hCharacter)
{
    MTH3D_tdstVector_ a2_stColons[2];
    MTH3D_tdstVector_ stAdding;
    MTH3D_tdstVector_ stPreviousRaisedPosition;
    MTH3D_tdstVector_ stCurrentRaisedPosition;
    HIE_tdstSuperObject_* hPreviousSector;
    HIE_tdstSuperObject_* hSector;
    HIE_tdstSuperObject_* hCurrentSector;
    MTH3D_tdstVector_ stCurrentPosition;
    tdstSectInfo_* p_stSectInfo;
    SECT_tdstSector_* p_stSector;
    SCT_tdstListOfSoundEvent_* hSoundEvent;
    int lNumberOfSoundEvent;

    p_stSectInfo = _hCharacter->hLinkedObject.p_stCharacter->h_SectInfo;

    if (p_stSectInfo->hSectorSynchroCharacter)
    {
        hSector = p_stSectInfo->hSectorSynchroCharacter->hLinkedObject.p_stCharacter->h_SectInfo->hCurrentSector;
        hPreviousSector = p_stSectInfo->hCurrentSector;
        *(int*)&stCurrentPosition.xX = *(int*)&_hCharacter->hGlobalMatrix->stTransformMatrix.stCol_3.xX;
        *(int*)&stCurrentPosition.xY = *(int*)&_hCharacter->hGlobalMatrix->stTransformMatrix.stCol_3.xY;
        *(int*)&stCurrentPosition.xZ = *(int*)&_hCharacter->hGlobalMatrix->stTransformMatrix.stCol_3.xZ;
    }
    else
    {
        MAT_fn_vGetRotationVectors(_hCharacter->hGlobalMatrix, &a2_stColons[0], &a2_stColons[1], &stAdding);
        stAdding.xX = 0.2f * stAdding.xX;
        stAdding.xY = 0.2f * stAdding.xY;
        stAdding.xZ = 0.2f * stAdding.xZ;
        hSector = p_stSectInfo->hCurrentSector;
        hPreviousSector = p_stSectInfo->hCurrentSector;
        *(int*)&stCurrentPosition.xX = *(int*)&_hCharacter->hGlobalMatrix->stTransformMatrix.stCol_3.xX;
        *(int*)&stCurrentPosition.xY = *(int*)&_hCharacter->hGlobalMatrix->stTransformMatrix.stCol_3.xY;
        *(int*)&stCurrentPosition.xZ = *(int*)&_hCharacter->hGlobalMatrix->stTransformMatrix.stCol_3.xZ;
        stCurrentRaisedPosition.xX = stCurrentPosition.xX + stAdding.xX;
        stCurrentRaisedPosition.xY = stCurrentPosition.xY + stAdding.xY;
        stCurrentRaisedPosition.xZ = stCurrentPosition.xZ + stAdding.xZ;
        stPreviousRaisedPosition.xX = p_stSectInfo->stPreviousPosition.xX + stAdding.xX;
        stPreviousRaisedPosition.xY = p_stSectInfo->stPreviousPosition.xY + stAdding.xY;
        stPreviousRaisedPosition.xZ = p_stSectInfo->stPreviousPosition.xZ + stAdding.xZ;
        SCT_fn_vTestChangeSectorWithHistory(&stPreviousRaisedPosition, &stCurrentRaisedPosition, &hSector);
    }

    hCurrentSector = p_stSectInfo->hCurrentSector;

    if (hSector != hCurrentSector)
    {
        if (_hCharacter == (HIE_tdstSuperObject_*)g_hCharacterLauchingSoundEvents)
        {
            p_stSector = hSector->hLinkedObject.p_stSector;
            lNumberOfSoundEvent = p_stSector->stListOfSoundEvent.lNumberOfElementsOpt;
            hSoundEvent = p_stSector->stListOfSoundEvent.hFirstElementOpt;
            while (lNumberOfSoundEvent)
            {
                if ((hSoundEvent->hPointerOfSectorSO == hCurrentSector) || (hSoundEvent->hPointerOfSectorSO == NULL))
                {
                    SND_fn_s32SendRequestSound(-1, -1, g_lSoundObjectTypeMusic, hSoundEvent->uSoundEvent, 0, 0);
                }
                lNumberOfSoundEvent--;
                hSoundEvent++;
            }
        }

        p_stSectInfo->hCurrentSector = hSector;

        if ((!fn_ucIsAnAlwaysObject(_hCharacter->hLinkedObject.p_stCharacter)) &&
            (!fn_bGetIfCharacterIsInAlwaysActiveCharacterListAndDynamicallyActived(_hCharacter)) &&
            (hSector->hLinkedObject.p_stSector->cCurrentActivity != 1))
        {
            HIE_fn_vIsolate(_hCharacter);

            if (_hCharacter->hLinkedObject.p_stCharacter->h_StandardGame->ucPlatFormType)
            {
                _hCharacter->hNextBrotherDyn = gp_stInactiveDynamicWorld->hFirstElementDyn;
                _hCharacter->hFatherDyn = gp_stInactiveDynamicWorld;
                if (gp_stInactiveDynamicWorld->hLastElementDyn)
                {
                    gp_stInactiveDynamicWorld->hFirstElementDyn->hPrevBrotherDyn = _hCharacter;
                }
                else
                {
                    gp_stInactiveDynamicWorld->hLastElementDyn = _hCharacter;
                }
                gp_stInactiveDynamicWorld->hFirstElementDyn = _hCharacter;
                gp_stInactiveDynamicWorld->lNumberOfElementsDyn++;
            }
            else
            {
                if (_hCharacter->hNextBrotherDyn)
                {
                    _hCharacter->hNextBrotherDyn->hPrevBrotherDyn = _hCharacter->hPrevBrotherDyn;
                }
                if (_hCharacter->hPrevBrotherDyn)
                {
                    _hCharacter->hPrevBrotherDyn->hNextBrotherDyn = _hCharacter->hNextBrotherDyn;
                }
                if (_hCharacter->hFatherDyn)
                {
                    _hCharacter->hFatherDyn->lNumberOfElementsDyn--;
                    if (_hCharacter->hFatherDyn->hFirstElementDyn == _hCharacter)
                    {
                        _hCharacter->hFatherDyn->hFirstElementDyn = _hCharacter->hNextBrotherDyn;
                    }
                    if (_hCharacter->hFatherDyn->hLastElementDyn == _hCharacter)
                    {
                        _hCharacter->hFatherDyn->hLastElementDyn = _hCharacter->hPrevBrotherDyn;
                }
                }
                _hCharacter->hNextBrotherDyn = NULL;
                _hCharacter->hPrevBrotherDyn = NULL;
                _hCharacter->hFatherDyn = NULL;
                _hCharacter->hNextBrotherDyn = NULL;
                _hCharacter->hPrevBrotherDyn = gp_stInactiveDynamicWorld->hLastElementDyn;
                _hCharacter->hFatherDyn = gp_stInactiveDynamicWorld;
                if (gp_stInactiveDynamicWorld->hLastElementDyn)
                {
                    gp_stInactiveDynamicWorld->hLastElementDyn->hNextBrotherDyn = _hCharacter;
                }
                else
                {
                    gp_stInactiveDynamicWorld->hFirstElementDyn = _hCharacter;
                }
                gp_stInactiveDynamicWorld->hLastElementDyn = _hCharacter;
                gp_stInactiveDynamicWorld->lNumberOfElementsDyn++;
            }

            _hCharacter->hLinkedObject.p_stCharacter->h_StandardGame->ucMiscFlags &= ~0x4;
        }

        SECT_fn_vIsolateCharListNode(_hCharacter->hLinkedObject.p_stCharacter->h_SectInfo->hNodeInSector);
        if (_hCharacter->hLinkedObject.p_stCharacter->h_StandardGame->ucPlatFormType)
        {
            SECT_fn_vAddHeadCharListNode(p_stSectInfo->hCurrentSector, _hCharacter->hLinkedObject.p_stCharacter->h_SectInfo->hNodeInSector);
        }
        else
        {
            SECT_fn_vAddTailCharListNode(p_stSectInfo->hCurrentSector, _hCharacter->hLinkedObject.p_stCharacter->h_SectInfo->hNodeInSector);
        }

        if (_hCharacter->hLinkedObject.p_stCharacter->h_MSLight)
        {
            fn_vInsertLightInSectorList(p_stSectInfo->hCurrentSector, _hCharacter);
        }

        if (MC_fn_ucIsCharacterInMainCharacterList(_hCharacter))
        {
            fn_vInitObjectsWhenPlayerChangeSector(_hCharacter, p_stSectInfo->hCurrentSector, hPreviousSector);
        }
    }

    *(int*)&p_stSectInfo->stPreviousPosition.xX = *(int*)&stCurrentPosition.xX;
    *(int*)&p_stSectInfo->stPreviousPosition.xY = *(int*)&stCurrentPosition.xY;
    *(int*)&p_stSectInfo->stPreviousPosition.xZ = *(int*)&stCurrentPosition.xZ;
}

void COL_fn_vCollideStaticElementSpheresWithStaticOctree(COL_tdstGVForCollision_* p_stGV)
{
    short xIndexNode __attribute__((aligned(16)));
    short xNbSubNodes __attribute__((aligned(16)));
    short xIndex __attribute__((aligned(16)));
    MTH4D_tdstVector_ stVect1;
    MTH4D_tdstVector_ stVect2;
    MTH3D_tdstVector_ stMinPoint __attribute__((aligned(16)));
    MTH3D_tdstVector_ stMaxPoint __attribute__((aligned(16)));
    MTH3D_tdstVector_* pV1;
    MTH3D_tdstVector_* pV2;
    MTH3D_tdstVector_* pV3;
    MTH4D_tdstMatrix_* pMat0;
    MTH4D_tdstMatrix_* pMat1;
    MTH4D_tdstVector_* pVect1;
    MTH4D_tdstVector_* pVect2;
    MTH3D_tdstVector_* p_stCenter;
    int* pSrc;
    MTH3D_tdstVector_* p_stEdgeNormal;
    COL_tdstOctreeNode_* p_stNode;
    unsigned char* p_xListIndex;
    short sIndex;
    short xEdge;
    unsigned char ucIndex;
    long lValue;

    for (xIndex = 0; xIndex < p_stGV->p_stDynamicElementSpheres->xNbSpheres; xIndex++)
    {
        p_stGV->p_stDynamicIndexedSphere = &p_stGV->p_stDynamicElementSpheres->d_stListOfSpheres[xIndex];
        p_stGV->p_stDynamicCenter = &p_stGV->p_stDynamicColObj->d_stListOfPoints[p_stGV->p_stDynamicIndexedSphere->xCenterPoint];
        p_stGV->xDynamicRadius = p_stGV->p_stDynamicIndexedSphere->xRadius / p_stGV->xStaticScale;

        pMat0 = &p_stGV->stD2ST0TransformMatrix.stTransformMatrix;
        pVect1 = &stVect1;
        p_stCenter = p_stGV->p_stDynamicCenter;
        pSrc = (int*)p_stCenter;
        *(int*)&stVect1.xY = pSrc[1];
        *(int*)&stVect1.xZ = pSrc[2];
        *(int*)&stVect1.xX = pSrc[0];
        asm {
            lqc2 vf1, 0x0(pVect1)
            lqc2 vf2, 0x0(pMat0)
            lqc2 vf3, 0x10(pMat0)
            lqc2 vf4, 0x20(pMat0)
            lqc2 vf5, 0x30(pMat0)
            vmulax.xyzw ACC, vf2, vf1x
            vmadday.xyzw ACC, vf3, vf1y
            vmaddaz.xyzw ACC, vf4, vf1z
            vmaddw.xyzw vf6, vf5, vf0w
            nop
            nop
            sqc2 vf6, 0x0(pVect1)
        }
        *(int*)&p_stGV->stDinST0Point.xX = *(int*)&stVect1.xX;
        *(int*)&p_stGV->stDinST0Point.xY = *(int*)&stVect1.xY;
        *(int*)&p_stGV->stDinST0Point.xZ = *(int*)&stVect1.xZ;

        pMat1 = &p_stGV->stD2ST1TransformMatrix.stTransformMatrix;
        pVect2 = &stVect2;
        *(int*)&stVect2.xX = *(int*)&p_stCenter->xX;
        *(int*)&stVect2.xY = *(int*)&p_stCenter->xY;
        *(int*)&stVect2.xZ = *(int*)&p_stCenter->xZ;
        asm {
            lqc2 vf1, 0x0(pVect2)
            lqc2 vf2, 0x0(pMat1)
            lqc2 vf3, 0x10(pMat1)
            lqc2 vf4, 0x20(pMat1)
            lqc2 vf5, 0x30(pMat1)
            vmulax.xyzw ACC, vf2, vf1x
            vmadday.xyzw ACC, vf3, vf1y
            vmaddaz.xyzw ACC, vf4, vf1z
            vmaddw.xyzw vf6, vf5, vf0w
            nop
            nop
            sqc2 vf6, 0x0(pVect2)
        }
        *(int*)&p_stGV->stDinST1Point.xX = *(int*)&stVect2.xX;
        *(int*)&p_stGV->stDinST1Point.xY = *(int*)&stVect2.xY;
        *(int*)&p_stGV->stDinST1Point.xZ = *(int*)&stVect2.xZ;

        p_stGV->stDinST01Vector.xX = p_stGV->stDinST1Point.xX - p_stGV->stDinST0Point.xX;
        p_stGV->stDinST01Vector.xY = p_stGV->stDinST1Point.xY - p_stGV->stDinST0Point.xY;
        p_stGV->stDinST01Vector.xZ = p_stGV->stDinST1Point.xZ - p_stGV->stDinST0Point.xZ;

        COL_fn_vEnlargeSphereIfNecessary(p_stGV);
        COL_fn_vComputeBoundingBoxOfSphere(&stMinPoint, &stMaxPoint, &p_stGV->stDinST0Point, p_stGV->xDynamicRadius);
        COL_fn_vExploreOctreeWithBox(p_stGV->p_stOctree, &stMinPoint, &stMaxPoint, (COL_tdstOctreeNode_**)p_stGV->aDEF_pstSelectedNode, &p_stGV->xNumberOfSelectedNodes);

        COL_g_lFacesTagCounter++;
        xIndexNode = 0;
        while (xIndexNode < p_stGV->xNumberOfSelectedNodes)
        {
            p_stNode = (COL_tdstOctreeNode_*)p_stGV->aDEF_pstSelectedNode[xIndexNode];
            p_xListIndex = (unsigned char*)p_stNode->d_xFaceIndexList;
            xNbSubNodes = *(short*)p_xListIndex;
            p_xListIndex += 2;
            for (ucIndex = 0; ucIndex < xNbSubNodes; ucIndex++)
            {
                if (p_xListIndex[0] < 0x80)
                {
                    p_stGV->xStaticElementIndex = (short)(p_xListIndex[0] & 0xFF);
                    p_xListIndex += 1;
                }
                else
                {
                    lValue = (short)(p_xListIndex[0] & 0xFF);
                    lValue = (short)((int)lValue << 8);
                    lValue = (short)((int)lValue + p_xListIndex[1]);
                    p_stGV->xStaticElementIndex = (short)(lValue & 0x7FFF);
                    p_xListIndex += 2;
                }

                if (p_xListIndex[0] < 0x80)
                {
                    lValue = (short)(p_xListIndex[0] & 0xFF);
                    p_xListIndex += 1;
                }
                else
                {
                    lValue = (short)(p_xListIndex[0] & 0xFF);
                    lValue = (short)((int)lValue << 8);
                    lValue = (short)((int)lValue + p_xListIndex[1]);
                    lValue = (short)(lValue & 0x7FFF);
                    p_xListIndex += 2;
                }

                sIndex = (short)lValue;
                if (COL_g_lFacesTagCounter != COL_g_d_lTaggedFacesTable[sIndex + p_stGV->p_stOctree->d_xElementBasesTable[p_stGV->xStaticElementIndex]])
                {
                    switch (((short*)p_stGV->p_stStaticColObj->d_xListOfElementsTypes)[p_stGV->xStaticElementIndex])
                    {
                        case 1:
                            if (p_stGV->ulSelectedCollisionCases & 0x20000)
                            {
                                p_stGV->p_stStaticElementIndexedTriangles = (COL_tdstElementIndexedTriangles_*)p_stGV->p_stStaticColObj->d_stListOfElements[p_stGV->xStaticElementIndex];
                                p_stGV->xStaticIndexedTriangleIndex = sIndex;
                                p_stGV->hDynamicMaterial = p_stGV->p_stDynamicIndexedSphere->hMaterial;
                                p_stGV->hStaticMaterial = p_stGV->p_stStaticElementIndexedTriangles->hMaterial;
                                if (COL_fn_bIsCollisionPossibleStaticSphereWithStaticIndexedTriangle(p_stGV) &&
                                    !COL_fn_bCollideStaticSphereWithStaticIndexedTriangle(p_stGV, 0))
                                {
                                    if (p_stGV->ulSelectedCollisionCases & 0x800)
                                    {
                                        COL_tdstTripledIndex_* pTriple;
                                        MTH3D_tdstVector_* pV4;
                                        short xEdgeIndex;

                                        pTriple = &p_stGV->p_stStaticElementIndexedTriangles->d_stListOfFacesTripled[sIndex];
                                        pV1 = &p_stGV->p_stStaticColObj->d_stListOfPoints[pTriple->a3_xIndex[0]];
                                        pV2 = &p_stGV->p_stStaticColObj->d_stListOfPoints[pTriple->a3_xIndex[1]];
                                        pV3 = &p_stGV->p_stStaticColObj->d_stListOfPoints[pTriple->a3_xIndex[2]];
                                        for (xEdge = 0; xEdge < 3; xEdge++)
                                        {
                                            p_stGV->p_stVertex1 = pV1;
                                            p_stGV->p_stVertex2 = pV2;
                                            p_stGV->stEdgeVector.xX = p_stGV->p_stVertex2->xX - p_stGV->p_stVertex1->xX;
                                            p_stGV->stEdgeVector.xY = p_stGV->p_stVertex2->xY - p_stGV->p_stVertex1->xY;
                                            p_stGV->stEdgeVector.xZ = p_stGV->p_stVertex2->xZ - p_stGV->p_stVertex1->xZ;
                                            p_stGV->p_stVertex2 = pV3;
                                            p_stGV->hDynamicMaterial = p_stGV->p_stDynamicIndexedSphere->hMaterial;
                                            p_stGV->hStaticMaterial = p_stGV->p_stStaticElementIndexedTriangles->hMaterial;
                                            xEdgeIndex = p_stGV->p_stStaticElementIndexedTriangles->d_stListOfFacesEdges[sIndex].a3_xIndex[xEdge];
                                            COL_g_xEdgeCoeffForNewComputations = p_stGV->p_stStaticElementIndexedTriangles->d_xListOfEdgesCoeff[xEdgeIndex];
                                            p_stEdgeNormal = &p_stGV->p_stStaticElementIndexedTriangles->d_stListOfEdgesNormals[xEdgeIndex];
                                            COL_g_p_stEdgeNormalForNewComputations = &p_stGV->p_stStaticElementIndexedTriangles->d_stListOfFacesNormals[sIndex];
                                            COL_fn_vCollideStaticSphereWithStaticEdge(p_stGV, p_stEdgeNormal);
                                            pV4 = pV1;
                                            pV1 = pV2;
                                            pV2 = pV3;
                                            pV3 = pV4;
                                        }
                                    }
                                }
                            }
                            break;
                        case 7:
                            if (p_stGV->ulSelectedCollisionCases & 0x80000)
                            {
                                p_stGV->p_stStaticElementSpheres = (COL_tdstElementSpheres_*)p_stGV->p_stStaticColObj->d_stListOfElements[p_stGV->xStaticElementIndex];
                                p_stGV->hDynamicMaterial = p_stGV->p_stDynamicIndexedSphere->hMaterial;
                                p_stGV->hStaticMaterial = p_stGV->p_stStaticIndexedSphere->hMaterial;
                                COL_fn_vCollideStaticSphereWithStaticSphere(p_stGV);
                            }
                            break;
                    }
                    COL_g_d_lTaggedFacesTable[sIndex + p_stGV->p_stOctree->d_xElementBasesTable[p_stGV->xStaticElementIndex]] = COL_g_lFacesTagCounter;
                }
            }
            xIndexNode++;
        }
    }
}

int GLI_Material_fn_lSetTextureOp(GLI_tdstMaterial_* _hVisualMat, int _lIndex, int _lTextureOp)
{
    int lOffset;
    if (_lIndex < 0 || _lIndex >= 4)
        return 0;
    lOffset = _lIndex * 80;
    ((char*)&_hVisualMat->a_stMultiMaterial[0].c_Operator)[lOffset] = _lTextureOp;
    return 1;
}

void GLI_vDrawIndexedSprite(GLD_tdstViewportAttributes_* p_stVpt, GEO_tdstGeometricObject_* p_stObj, GEO_tdstIndexedSprite_* p_stISpr)
{
    MAT_tdstTransformation_ TempMatrix;
    float coords[4][3];
    float fScaleX;
    float fScaleY;
    MTH3D_tdstVector_ CenterPoint;
    MTH4D_tdstVector_ CameraCenterPoint;
    MTH3D_tdstVector_ vecX;
    MTH3D_tdstVector_ vecY;
    float x;
    float y;
    float z;
    int i;

    if (p_stISpr->hSprite == NULL) return;
    if (p_stVpt == NULL) return;
    if ((short)p_stISpr->hSprite->d_xSpriteDrawMode & 4) return;

    MAT_fn_vInvert(&TempMatrix, (char*)*(void**)p_stVpt->p_vSpecificToXD + 0x10);

    fScaleX = p_stISpr->hSprite->d_xSizeOfSprite->xX;
    fScaleY = -p_stISpr->hSprite->d_xSizeOfSprite->xY;
    vecX.xX = TempMatrix.stTransformMatrix.stCol_0.xX * fScaleX;
    vecX.xY = TempMatrix.stTransformMatrix.stCol_0.xY * fScaleX;
    vecX.xZ = TempMatrix.stTransformMatrix.stCol_0.xZ * fScaleX;
    vecY.xX = TempMatrix.stTransformMatrix.stCol_1.xX * fScaleY;
    vecY.xY = TempMatrix.stTransformMatrix.stCol_1.xY * fScaleY;
    vecY.xZ = TempMatrix.stTransformMatrix.stCol_1.xZ * fScaleY;
    if ((short)p_stISpr->hSprite->d_xSpriteDrawMode & 0x10) return;

    switch (GLI_BIG_GLOBALS_gs_st_CurrentMatrix->eType)
    {
    case 8: break;
    case 6:
    case 7:
    case 3:
    case 4:
    default:
        fScaleX = MAT_fn_xGetXScale(&GLI_BIG_GLOBALS_gs_st_CurrentMatrixMultiplyedWithCameraMatrix.stTransformMatrix);
        fScaleY = MAT_fn_xGetYScale(&GLI_BIG_GLOBALS_gs_st_CurrentMatrixMultiplyedWithCameraMatrix.stTransformMatrix);
        break;
    }

    CenterPoint.xX = p_stObj->d_stListOfPoints[p_stISpr->xCenterPoint].xX;
    CenterPoint.xY = p_stObj->d_stListOfPoints[p_stISpr->xCenterPoint].xY;
    CenterPoint.xZ = p_stObj->d_stListOfPoints[p_stISpr->xCenterPoint].xZ;
    *(int*)&CameraCenterPoint.xX = *(int*)&CenterPoint.xX;
    *(int*)&CameraCenterPoint.xY = *(int*)&CenterPoint.xY;
    *(int*)&CameraCenterPoint.xZ = *(int*)&CenterPoint.xY;

    {
        float* pMat = (float*)&GLI_BIG_GLOBALS_gs_st_CurrentMatrix->stTransformMatrix;
        float* pVec = (float*)&CameraCenterPoint;
        asm {
            lqc2 $vf1, 0x0(pVec)
            lqc2 $vf2, 0x0(pMat)
            lqc2 $vf3, 0x10(pMat)
            lqc2 $vf4, 0x20(pMat)
            lqc2 $vf5, 0x30(pMat)
            vmulax.xyzw $ACC, $vf2, $vf1x
            vmadday.xyzw $ACC, $vf3, $vf1y
            vmaddaz.xyzw $ACC, $vf4, $vf1z
            vmaddw.xyzw $vf6, $vf5, $vf1w
            sqc2 $vf6, 0x0(pVec)
        }
    }

    x = CameraCenterPoint.xX;
    y = CameraCenterPoint.xY;
    z = CameraCenterPoint.xZ;
    coords[0][0] = vecY.xX + (x + vecX.xX);
    coords[0][1] = vecY.xY + (y + vecX.xY);
    coords[0][2] = vecY.xZ + (z + vecX.xZ);
    coords[3][0] = (x + vecX.xX) - vecY.xX;
    coords[3][1] = (y + vecX.xY) - vecY.xY;
    coords[3][2] = (z + vecX.xZ) - vecY.xZ;
    coords[1][0] = vecY.xX + (x - vecX.xX);
    coords[1][1] = vecY.xY + (y - vecX.xY);
