void MEC_fn_vCrashAnalysis(DNM_stDynamics* p_stDynamic, int lObstacle, DNM_stMecObstacle* p_stObstacle)
{
    int lCounter = 0;
    DNM_stMecObstacle* p_stTmpObstacle = p_stObstacle;
    DNM_stMecObstacle* p_stGroundObstacle = NULL;
    DNM_stMecObstacle* p_stCeilObstacle = NULL;

    p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags &= 0xFFF7FFFF;

    for (lCounter = 0; lCounter < lObstacle; lCounter++)
    {
        if ((unsigned char)(p_stTmpObstacle->m_xCollidedEntity != 99))
        {
            if ((p_stGroundObstacle == NULL) && MEC_fn_bGroundNormal(p_stDynamic, &p_stTmpObstacle->m_stNorm))
            {
                p_stGroundObstacle = p_stTmpObstacle;
            }
            if ((p_stCeilObstacle == NULL) && MEC_fn_bCeilObstacle(p_stDynamic, p_stTmpObstacle))
            {
                p_stCeilObstacle = p_stTmpObstacle;
            }
        }
        p_stTmpObstacle++;
    }

    if (p_stCeilObstacle == NULL)
    {
        return;
    }
    if (p_stGroundObstacle == NULL)
    {
        return;
    }
    if (((p_stGroundObstacle->m_eType & 2) && MEC_fn_bCanCrashActor(p_stGroundObstacle)) || ((p_stCeilObstacle->m_eType & 2) && MEC_fn_bCanCrashActor(p_stCeilObstacle)))
    {
        p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags |= 0x80000;
    }
}

void IPO_fn_vFrameEndForRLITables(void)
{
    char cMode;
    int lFlag;
    int lFlag2;
    long lEnd;
    HIE_tdstSuperObject_* hChild;
    HIE_tdstSuperObject_* hWorld;
    IPO_tdstInstanciatedPhysicalObject_* hIPO;

    if (IPO_g_cTransitionInProgress)
    {
        cMode = IPO_g_cChangeMode;
        lFlag = 1;
        lEnd = 0;
        if (cMode == 1)
        {
            if (IPO_g_fCurrentGlobalRatio >= 1.0f)
            {
                IPO_g_ucCurrentRadiosityIndex = IPO_g_ucNextRadiosityIndex;
                if (IPO_g_ucCurrentRadiosityIndex == IPO_g_ucRadiosityIndexToReach)
                {
                    lEnd = lFlag;
                }
                else
                {
                    IPO_g_fCurrentGlobalRatio = 0.0f;
                    IPO_g_fIncrementByMilliSecond = 0.0f;
                    IPO_g_ucNextRadiosityIndex = (unsigned char)((IPO_g_ucCurrentRadiosityIndex + 1) % IPO_g_ucNumberOfRLITables);
                }
            }
        }
        else if (cMode == 2)
        {
            float fWanted = IPO_g_fAddWantedRatio;

            lFlag = 1;
            if (fWanted <= 0.0f)
            {
                lFlag = 0;
            }
            if (lFlag != 0)
            {
                if (IPO_g_fCurrentGlobalRatio < fWanted)
                {
                    lFlag = 0;
                }
                else
                {
                    lFlag = 1;
                }
            }
            if (lFlag == 0)
            {
                lFlag2 = 1;
                if (!(fWanted < 0.0f))
                {
                    lFlag2 = 0;
                }
                if (lFlag2 != 0)
                {
                    if (IPO_g_fCurrentGlobalRatio <= fWanted)
                    {
                        lFlag2 = 1;
                    }
                    else
                    {
                        lFlag2 = 0;
                    }
                }
                lEnd = (long)lFlag2;
            }
        }
        else
        {
            lEnd = 1;
        }
        if (lEnd != 0)
        {
            hWorld = gp_stActualWorld;
            IPO_g_fPreviousGlobalRatio = IPO_g_fCurrentGlobalRatio;
            for (hChild = hWorld->hFirstElementDyn; hChild != NULL; hChild = hChild->hNextBrotherDyn)
            {
                IPO_fn_vUpdateAllIPOAfterTransition(hChild);
            }
            if (hWorld->ulTypeOfLinkedObject == 0x20)
            {
                hIPO = hWorld->hLinkedObject.p_stInstanciatedPhysicalObject;
                lFlag = 0;
                if (hIPO->ulLastTransitionID == IPO_g_ulCurrentTransitionID)
                {
                    if (hIPO->fLastRatioUsed == IPO_g_fPreviousGlobalRatio)
                    {
                        lFlag = 1;
                    }
                }
                if (lFlag == 0)
                {
                    IPO_fn_vInternalComputeRLI(hIPO, IPO_g_fCurrentGlobalRatio);
                }
            }
            IPO_g_cChangeMode = 0;
            IPO_g_fIncrementByMilliSecond = 0.0f;
            IPO_g_fCurrentGlobalRatio = 0.0f;
            IPO_g_cTransitionInProgress = 0;
        }
    }
}

void GLI_vComputeEdges(void)
{
    GEO_tdstTripledIndex_* p_stPointIndex;
    GEO_tdstDoubledIndexDWORD_* p_stListOfEdges;
    short xElementCounter;
    unsigned int ulNbrEdge;
    GEO_tdstElementIndexedTriangles_* p_stEIT;
    GEO_tdstTripledIndexDWORD_* p_stEdgeIndex;
    unsigned int ulFaceIndex;
    short sResult;
    int bOk;

    ulNbrEdge = 0;
    p_stListOfEdges = (GEO_tdstDoubledIndexDWORD_*)GLI_BIG_GLOBALS_GLI_TurnedScaledDisplecedPoint;
    for (xElementCounter = 0; xElementCounter < ((GEO_tdstGeometricObject_*)GLI_BIG_GLOBALS_p_stObj)->xNbElements; xElementCounter++)
    {
        if (((short*)((GEO_tdstGeometricObject_*)GLI_BIG_GLOBALS_p_stObj)->d_xListOfElementsTypes)[xElementCounter] != 1)
            continue;
        p_stEIT = ((GEO_tdstElementIndexedTriangles_**)((GEO_tdstGeometricObject_*)GLI_BIG_GLOBALS_p_stObj)->d_stListOfElements)[xElementCounter];
        bOk = 0;
        if (p_stEIT->hVisualMaterial != NULL)
        {
            if (p_stEIT->hVisualMaterial->lMaterialAdditionnalType & 8)
            {
                bOk = 1;
            }
        }
        if (bOk)
        {
            p_stEdgeIndex = (GEO_tdstTripledIndexDWORD_*)HMU_fn_p_vMalloc(p_stEIT->xNbFaces * 3 * sizeof(GEO_tdstTripledIndexDWORD_), 1);
            p_stEIT->d_stListOfFacesEdges = (GEO_tdstTripledIndex_*)p_stEdgeIndex;
            p_stPointIndex = p_stEIT->d_stListOfFacesTripled;
            for (ulFaceIndex = 0; ulFaceIndex < p_stEIT->xNbFaces; ulFaceIndex++, p_stPointIndex++, p_stEdgeIndex++)
            {
                GLI_M_xGetEdgeIndex(sResult, p_stPointIndex->a3_xIndex[0], p_stPointIndex->a3_xIndex[1]);
                p_stEdgeIndex->a3_xIndex[0] = sResult;
                GLI_M_xGetEdgeIndex(sResult, p_stPointIndex->a3_xIndex[1], p_stPointIndex->a3_xIndex[2]);
                p_stEdgeIndex->a3_xIndex[1] = sResult;
                GLI_M_xGetEdgeIndex(sResult, p_stPointIndex->a3_xIndex[2], p_stPointIndex->a3_xIndex[0]);
                p_stEdgeIndex->a3_xIndex[2] = sResult;
            }
        }
    }
    ((GEO_tdstGeometricObject_*)GLI_BIG_GLOBALS_p_stObj)->d_stListOfEdgesDI = (GEO_tdstDoubledIndex_*)HMU_fn_p_vMalloc(ulNbrEdge * sizeof(GEO_tdstDoubledIndexDWORD_), 1);
    memcpy(((GEO_tdstGeometricObject_*)GLI_BIG_GLOBALS_p_stObj)->d_stListOfEdgesDI, p_stListOfEdges, ulNbrEdge * sizeof(GEO_tdstDoubledIndexDWORD_));
    ((GEO_tdstGeometricObject_*)GLI_BIG_GLOBALS_p_stObj)->xNbEdgesDI = (short)ulNbrEdge;
}

