                if ((p_stTmpObstacle->hCollidedMaterial->hCollideMaterial != NULL) &&
                    (((p_stTmpObstacle->hCollidedMaterial->hCollideMaterial->xIdentifier & 0x4000) == 0x4000) ? 1 : 0) &&
