void fn_RotateVectorByAngle(MTH3D_tdstVector_* vector1, float xAngle, MTH3D_tdstVector_* vector2)
{
    float xSaveX;
    float xSaveY;
    float xSaveZ;
    MTH3D_tdstVector_ vTemp;
    MTH4D_tdstMatrix_ stMatrix;
    *(int*)&vTemp.xX = *(int*)&vector2->xX;
    *(int*)&vTemp.xY = *(int*)&vector2->xY;
    *(int*)&vTemp.xZ = *(int*)&vector2->xZ;
    if (xAngle != 0.0f)
    {
        float xHalf = 0.5f;
        xAngle = xAngle * -xHalf;
        vTemp.xX = vTemp.xX * sinf(xAngle); vTemp.xY = vTemp.xY * sinf(xAngle); vTemp.xZ = vTemp.xZ * sinf(xAngle);
        MAT_fn_vQuatToMatrix(&stMatrix, vTemp.xX, vTemp.xY, vTemp.xZ, cosf(xAngle));
        if (vector1 == &vTemp)
        {
            *(int*)&xSaveX = *(int*)&vector1->xX; *(int*)&xSaveY = *(int*)&vector1->xY; *(int*)&xSaveZ = *(int*)&vector1->xZ;
            vTemp.xX = stMatrix.stCol_0.xX * xSaveX + stMatrix.stCol_1.xX * xSaveY + stMatrix.stCol_2.xX * xSaveZ;
            vTemp.xY = stMatrix.stCol_0.xY * xSaveX + stMatrix.stCol_1.xY * xSaveY + stMatrix.stCol_2.xY * xSaveZ;
            vTemp.xZ = stMatrix.stCol_0.xZ * xSaveX + stMatrix.stCol_1.xZ * xSaveY + stMatrix.stCol_2.xZ * xSaveZ;
        }
        else
        {
            vTemp.xX = stMatrix.stCol_0.xX * vector1->xX + stMatrix.stCol_1.xX * vector1->xY + stMatrix.stCol_2.xX * vector1->xZ;
            vTemp.xY = stMatrix.stCol_0.xY * vector1->xX + stMatrix.stCol_1.xY * vector1->xY + stMatrix.stCol_2.xY * vector1->xZ;
            vTemp.xZ = stMatrix.stCol_0.xZ * vector1->xX + stMatrix.stCol_1.xZ * vector1->xY + stMatrix.stCol_2.xZ * vector1->xZ;
        }
        MTH3D_M_vCopyVector(vector1, &vTemp);
    }
}

void MAT_fn_vScale(MAT_tdstTransformation_* _hTransform, MTH3D_tdstVector_* _p_stScale)
{
    MTH4D_tdstMatrix_* p_stMatrix;
    unsigned char bUniformScale;
    float xScale;    if (MTH_xAbs(_p_stScale->xX - _p_stScale->xY) < 0.0001f)
    {
        if (MTH_xAbs(_p_stScale->xX - _p_stScale->xZ) < 0.0001f) { bUniformScale = 1; }
        else { bUniformScale = 0; }
    }
    else
    {
        bUniformScale = 0;
    }
    if (bUniformScale)
    {
        MAT_fn_vZoom(_hTransform, _p_stScale->xX);
        return;
    }

    p_stMatrix = &_hTransform->stTransformMatrix;

    switch (_hTransform->eType)
    {
    case MAT_eTransform_Identity:
    case MAT_eTransform_Translation:
        _hTransform->eType = MAT_eTransform_Scale;
        p_stMatrix->stCol_0.xX = _p_stScale->xX;
        p_stMatrix->stCol_1.xY = _p_stScale->xY;
        p_stMatrix->stCol_2.xZ = _p_stScale->xZ;
        *(int*)&_hTransform->stScaleVector.xX = *(int*)&_p_stScale->xX;
        *(int*)&_hTransform->stScaleVector.xY = *(int*)&_p_stScale->xY;
        *(int*)&_hTransform->stScaleVector.xZ = *(int*)&_p_stScale->xZ;
        break;

    case MAT_eTransform_Zoom:
        _hTransform->eType = MAT_eTransform_Scale;
        /* fall through */
    case MAT_eTransform_Scale:
        p_stMatrix->stCol_0.xX = p_stMatrix->stCol_0.xX * _p_stScale->xX;
        p_stMatrix->stCol_1.xY = p_stMatrix->stCol_1.xY * _p_stScale->xY;
        p_stMatrix->stCol_2.xZ = p_stMatrix->stCol_2.xZ * _p_stScale->xZ;
        break;

    case MAT_eTransform_Rotation:
    case MAT_eTransform_RotationZoom:
        _hTransform->eType = MAT_eTransform_RotationScale;
        /* fall through */
    case MAT_eTransform_RotationScale:
        _hTransform->stScaleVector.xX = _hTransform->stScaleVector.xX * _p_stScale->xX;
        _hTransform->stScaleVector.xY = _hTransform->stScaleVector.xY * _p_stScale->xY;
        _hTransform->stScaleVector.xZ = _hTransform->stScaleVector.xZ * _p_stScale->xZ;
        /* fall through */
    case MAT_eTransform_ComplexRotationScale:
        xScale = _p_stScale->xX;
        p_stMatrix->stCol_0.xX = xScale * p_stMatrix->stCol_0.xX;
        p_stMatrix->stCol_0.xY = xScale * p_stMatrix->stCol_0.xY;
        p_stMatrix->stCol_0.xZ = xScale * p_stMatrix->stCol_0.xZ;
        p_stMatrix->stCol_0.xW = 1.0f;
        xScale = _p_stScale->xY;
        p_stMatrix->stCol_1.xX = xScale * p_stMatrix->stCol_1.xX;
        p_stMatrix->stCol_1.xY = xScale * p_stMatrix->stCol_1.xY;
        p_stMatrix->stCol_1.xZ = xScale * p_stMatrix->stCol_1.xZ;
        p_stMatrix->stCol_1.xW = 1.0f;
        xScale = _p_stScale->xZ;
        p_stMatrix->stCol_2.xX = xScale * p_stMatrix->stCol_2.xX;
        p_stMatrix->stCol_2.xY = xScale * p_stMatrix->stCol_2.xY;
        p_stMatrix->stCol_2.xZ = xScale * p_stMatrix->stCol_2.xZ;
        p_stMatrix->stCol_2.xW = 1.0f;
        p_stMatrix->stCol_2.xW = 0.0f;
        p_stMatrix->stCol_1.xW = 0.0f;
        p_stMatrix->stCol_0.xW = 0.0f;
        break;
    }
}

void INT_fn_vViewAndAddFaceElementInList(short xNbMaxElements, short* p_xNbElements, GLI_tdstDataOfElement_* d_stDataOfElement, MTH3D_tdstVector_* p_stVertexA, unsigned char bBack, MTH3D_tdstVector_* p_stHit, short xElements, short xDataElementIndex)
{
    short xFaceIndex;
    float xDistance;

    if (bBack)
        return;

    MTH_DISTANCE_TO(xDistance, p_stVertexA, p_stHit);

    for (xFaceIndex = *p_xNbElements; xFaceIndex > 0 && xDistance < d_stDataOfElement[xFaceIndex-1].xDistance; xFaceIndex--)
    {
        memcpy(&d_stDataOfElement[xFaceIndex], &d_stDataOfElement[xFaceIndex-1], sizeof(GLI_tdstDataOfElement_));
    }

    if (xFaceIndex < xNbMaxElements)
    {
        *(int*)&d_stDataOfElement[xFaceIndex].stHit.xX = *(int*)&p_stHit->xX;
        *(int*)&d_stDataOfElement[xFaceIndex].stHit.xY = *(int*)&p_stHit->xY;
        *(int*)&d_stDataOfElement[xFaceIndex].stHit.xZ = *(int*)&p_stHit->xZ;
        ((float*)&d_stDataOfElement[0].xDistance)[xFaceIndex * 6] = xDistance;
        ((short*)&d_stDataOfElement[0].xElements)[xFaceIndex * 12] = xElements;
        ((short*)&d_stDataOfElement[0].xIndexOfFace)[xFaceIndex * 12] = xDataElementIndex;
        if (*p_xNbElements < xNbMaxElements)
        {
            *p_xNbElements = *p_xNbElements + 1;
        }
    }
}

void fn_vChangeCurrentValue(char Value)
{
    if (aMenu2DPages[g_CurrentMenu2DPage].aValue[g_CurrentSelection] != Value)
    {
        fn_vPlaySoundInGameMenu2D(3);
        aMenu2DPages[g_CurrentMenu2DPage].aValue[g_CurrentSelection] = Value;
    }

    switch (aMenu2DPages[g_CurrentMenu2DPage].eTypePage)
    {
    case eVideoOptionTypePage:
        if (g_CurrentSelection == 1)
        {
            GLI_g_bWideScreenMode = Value;
        }
        break;

    case eControlOptionTypePage:
        if (g_CurrentSelection == 0)
        {
            MENU_g_bInversionVert = Value;
        }
        else if (g_CurrentSelection == 1)
        {
            MENU_g_bInversionHor = Value;
        }
        else if (g_CurrentSelection == 2)
        {
            if (MENU_g_bVibration != Value)
            {
                MENU_g_bVibration = Value;

                if (Value != 0)
                {
                    if (g_MenuVibrationEffect != -1)
                    {
                        IPT_fn_vStopFFBEffect(g_stEngineStructure.stEngineTimer.ulCurrentTimerCount, 0, g_MenuVibrationEffect);
                        g_MenuVibrationEffect = -1;
                    }

                    IPT_fn_vResumeAllConstantFFBEffectForAllDevices(g_stEngineStructure.stEngineTimer.ulCurrentTimerCount);
                    g_MenuVibrationEffect = IPT_fn_cCreateAndLaunchConstantFFBEffect(g_stEngineStructure.stEngineTimer.ulCurrentTimerCount, 0, 1.0f, 0.0f, 1.0f, 0.0f, 0.0f, 1.0f);
                }
                else
                {
                    IPT_fn_vPauseAllConstantFFBEffectForAllDevices(g_stEngineStructure.stEngineTimer.ulCurrentTimerCount);
                }
            }
        }
        break;

    case eAudioOptionTypePage:
        fn_vSetStereoGameMenu2D(Value);
        break;
    }
}

