void MAT_fn_vApplyOnVector(MTH3D_tdstVector_* _p_stDest, MAT_tdstTransformation_* _hTransform, MTH3D_tdstVector_* _p_stSource)
{
    switch (_hTransform->eType)
    {
    case MAT_eTransform_Identity:
    case MAT_eTransform_Translation:
        if (_p_stDest != _p_stSource)
        {
            *(int*)&_p_stDest->xX = *(int*)&_p_stSource->xX;
            *(int*)&_p_stDest->xY = *(int*)&_p_stSource->xY;
            *(int*)&_p_stDest->xZ = *(int*)&_p_stSource->xZ;
        }
        break;

    case MAT_eTransform_Zoom:
    case MAT_eTransform_Scale:
        _p_stDest->xX = _p_stSource->xX * _hTransform->stScaleVector.xX;
        _p_stDest->xY = _p_stSource->xY * _hTransform->stScaleVector.xY;
        _p_stDest->xZ = _p_stSource->xZ * _hTransform->stScaleVector.xZ;
        break;

    case MAT_eTransform_Rotation:
    case MAT_eTransform_RotationZoom:
    case MAT_eTransform_RotationScale:
    case MAT_eTransform_ComplexRotationScale:
        if (_p_stSource == _p_stDest)
        {
            MTH3D_tdstVector_ stTemp;
            *(int*)&stTemp.xX = *(int*)&_p_stSource->xX;
            *(int*)&stTemp.xY = *(int*)&_p_stSource->xY;
            *(int*)&stTemp.xZ = *(int*)&_p_stSource->xZ;
            _p_stDest->xX = _hTransform->stTransformMatrix.stCol_0.xX * stTemp.xX + _hTransform->stTransformMatrix.stCol_1.xX * stTemp.xY + _hTransform->stTransformMatrix.stCol_2.xX * stTemp.xZ;
            _p_stDest->xY = _hTransform->stTransformMatrix.stCol_0.xY * stTemp.xX + _hTransform->stTransformMatrix.stCol_1.xY * stTemp.xY + _hTransform->stTransformMatrix.stCol_2.xY * stTemp.xZ;
            _p_stDest->xZ = _hTransform->stTransformMatrix.stCol_0.xZ * stTemp.xX + _hTransform->stTransformMatrix.stCol_1.xZ * stTemp.xY + _hTransform->stTransformMatrix.stCol_2.xZ * stTemp.xZ;
        }
        else
        {
            _p_stDest->xX = _hTransform->stTransformMatrix.stCol_0.xX * _p_stSource->xX + _hTransform->stTransformMatrix.stCol_1.xX * _p_stSource->xY + _hTransform->stTransformMatrix.stCol_2.xX * _p_stSource->xZ;
            _p_stDest->xY = _hTransform->stTransformMatrix.stCol_0.xY * _p_stSource->xX + _hTransform->stTransformMatrix.stCol_1.xY * _p_stSource->xY + _hTransform->stTransformMatrix.stCol_2.xY * _p_stSource->xZ;
            _p_stDest->xZ = _hTransform->stTransformMatrix.stCol_0.xZ * _p_stSource->xX + _hTransform->stTransformMatrix.stCol_1.xZ * _p_stSource->xY + _hTransform->stTransformMatrix.stCol_2.xZ * _p_stSource->xZ;
        }
        break;
    }
}

tdstNodeInterpret_* fn_p_stSetCheapCharacterPos(HIE_tdstSuperObject_* p_SuperObjPerso, tdstNodeInterpret_* p_stTree)
{
    unsigned int ulIndChar;
    _tdstCheapCharacterList* pCheapList;
    tdeProcedureId_ eProcedureId;
    unsigned int ulInd;
    tdstGetSetParam_ stParam;
    char* pc;
    int iIndex;

    eProcedureId = (p_stTree - 1)->uDummy;
    p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stParam);
    ulInd = stParam.uParam.ulValue;
    p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stParam);
    ulIndChar = stParam.uParam.ulValue;
    p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stParam);
    MTH3D_tdstVector_ stPosition = stParam.uParam.stVectorValue;
    pCheapList = &g_aListOfCheapCharacterList[ulInd];
    if (pCheapList->NumberOfCheapCharacter < ulIndChar)
        return p_stTree;
    if (eProcedureId == 842) {
        iIndex = (int)ulIndChar * 48;
        pc = (char*)pCheapList;
        pc = pc + 0x10;
        *(float*)((char*)pc + iIndex) = stPosition.x;
        pc = (char*)pCheapList;
        pc = pc + 0x14;
        *(float*)((char*)pc + iIndex) = stPosition.y;
        pc = (char*)pCheapList;
        pc = pc + 0x18;
        *(float*)((char*)pc + iIndex) = stPosition.z;
    } else if (eProcedureId == 843) {
        int iIdx;
        float fNorm;
        float* pfZ;
        float* pfY;
        float* pfX;

        iIdx = (int)ulIndChar * 48;
        pc = (char*)pCheapList;
        pc = pc + 0x20;
        pfX = (float*)((char*)pc + iIdx);
        pc = (char*)pCheapList;
        pc = pc + 0x24;
        pfY = (float*)((char*)pc + iIdx);
        pc = (char*)pCheapList;
        pc = pc + 0x28;
        pfZ = (float*)((char*)pc + iIdx);
        *pfX = stPosition.x;
        *pfY = stPosition.y;
        *pfZ = stPosition.z;
        fNorm = 1.0f / MTH_xSqrt(MTH_fn_xSqrAddSqrAddSqrOpt2(*pfX, *pfY, *pfZ));
        *pfX = fNorm * *pfX;
        *pfY = fNorm * *pfY;
        *pfZ = fNorm * *pfZ;
        pc = (char*)pCheapList;
        pc = pc + 0x2c;
        *(float*)((char*)pc + iIdx) = 1.0f;
    }
    return p_stTree;
}

float fn_xAngleVectorXOY(MTH3D_tdstVector_* stVectorU, MTH3D_tdstVector_* stVectorV)
{
    float xNorm;
    float xNorm2;
    MTH3D_tdstVector_ vUtemp2;
    MTH3D_tdstVector_ vUtemp;
    float xAngle;
    float xCos;
    vUtemp.xX = stVectorU->xX;
    vUtemp.xY = stVectorU->xY;
    *(int*)&vUtemp.xZ = 0;
    vUtemp2.xX = stVectorV->xX;
    vUtemp2.xY = stVectorV->xY;
    *(int*)&vUtemp2.xZ = 0;
    if (((vUtemp.xX == 0.0f) && (vUtemp.xY == 0.0f) && (vUtemp.xZ == 0.0f)) ||
        ((vUtemp2.xX == 0.0f) && (vUtemp2.xY == 0.0f) && (vUtemp2.xZ == 0.0f))) { return 0.0f; }
    MTH_SQR3_OF(xNorm, vUtemp);
    MTH_SQRT_TO(xNorm2, xNorm);
    if (xNorm2 != 0.0f)
    {
        xNorm2 = 1.0f / xNorm2;
        vUtemp.xX = xNorm2 * vUtemp.xX;
        vUtemp.xY = xNorm2 * vUtemp.xY;
        vUtemp.xZ = xNorm2 * vUtemp.xZ;
    }
    MTH_SQR3_OF(xNorm, vUtemp2);
    MTH_SQRT_TO(xNorm2, xNorm);
    if (xNorm2 != 0.0f)
    {
        xNorm2 = 1.0f / xNorm2;
        vUtemp2.xX = xNorm2 * vUtemp2.xX;
        vUtemp2.xY = xNorm2 * vUtemp2.xY;
        vUtemp2.xZ = xNorm2 * vUtemp2.xZ;
    }
    MTH_DOT3_OF(xCos, vUtemp, vUtemp2);
    if (xCos > 1.0f) { xCos = 1.0f; }
    if (xCos < -1.0f) { xCos = -1.0f; }
    xAngle = acosf(xCos);
    MTH_CROSS_Z_OF(xCos, vUtemp, vUtemp2);
    if (xCos < 0.0f) { xAngle = -xAngle; }
    return xAngle;
}

void GLI_vGet3DVertexFromScreenPos(GLD_tdstViewportAttributes_* p_stVpt, MTH3D_tdstVector_* p_stPos3D, float xRatioX, float xRatioY, float xSize)
{
    MAT_tdstTransformation_ stInvMatrix;
    MAT_tdstTransformation_ stMatrix;
    MTH3D_tdstVector_ stTemp;
    volatile float fCoeff;
    volatile float xScreen;
    volatile float fZ;
    GLI_tdstCamera_* p_stCam;
    float fWidth;
    float fX;
    float fY;
    int lVal;

    if (p_stVpt->dwWidth >= 0) fWidth = (float)p_stVpt->dwWidth; else
    {
        lVal = (int)(((unsigned int)p_stVpt->dwWidth >> 1) | (p_stVpt->dwWidth & 1));
        fWidth = (float)lVal + (float)lVal;
    }
    p_stCam = *(GLI_tdstCamera_**)p_stVpt->p_vSpecificToXD;
    fCoeff = fWidth / 1024.0f;
    fX = 1024.0f * xRatioX;
    fY = 0.5f * xRatioY;

    switch (p_stCam->lCameraMode)
    {
    case 100:
    case 101:
        xScreen = 0.1f;
        break;
    case 102:
    case 103:
        if (p_stVpt->dwWidth >= 0) fWidth = (float)p_stVpt->dwWidth; else
        {
            lVal = (int)(((unsigned int)p_stVpt->dwWidth >> 1) | (p_stVpt->dwWidth & 1));
            fWidth = (float)lVal + (float)lVal;
        }
        xScreen = (p_stCam->xScreen * fWidth) / 1024.0f;
        break;
    default:
        p_stPos3D->xZ = 0.0f;
        p_stPos3D->xY = 0.0f;
        p_stPos3D->xX = 0.0f;
        return;
    }

    if (xSize != 0.0f)
    {
        fCoeff = ((fX - p_stCam->stScale.xX) / p_stCam->stScale.xX) / xSize;
        xScreen = xScreen * ((1.0f + xSize) / xSize);
        fZ = 0.0f;
    }
    else
    {
        fCoeff = (fX - p_stCam->stScale.xX) / p_stCam->stScale.xX;
        xScreen = (fY - 240.0f) / p_stCam->stScale.xY;
        fZ = 0.0f;
    }

    stMatrix = p_stCam->stMatrix;
    MAT_fn_vInvert(&stInvMatrix, &stMatrix);

    stTemp.xX = fCoeff;
    stTemp.xY = xScreen;
    stTemp.xZ = fZ;
    {
        float* pMat = (float*)&stInvMatrix.stTransformMatrix;
        float* pVec = (float*)&stTemp;
        asm {
            lqc2 $vf1, 0x0(pVec)
            lqc2 $vf2, 0x0(pMat)
            lqc2 $vf3, 0x10(pMat)
            lqc2 $vf4, 0x20(pMat)
            lqc2 $vf5, 0x30(pMat)
            vmulax.xyzw $ACC, $vf2, $vf1x
            vmadday.xyzw $ACC, $vf3, $vf1y
            vmaddaz.xyzw $ACC, $vf4, $vf1z
            vmaddw.xyzw $vf6, $vf5, $vf0w
            sqc2 $vf6, 0x0(pVec)
        }
    }
    p_stPos3D->xX = stTemp.xX;
    p_stPos3D->xY = stTemp.xY;
    p_stPos3D->xZ = stTemp.xZ;
}

