float MAT_fn_xGetYScale(MAT_tdstTransformation_* _hTransform)
{
    float xScale;

    switch (_hTransform->eType)
    {
    case MAT_eTransform_Identity:
    case MAT_eTransform_Translation:
    case MAT_eTransform_Rotation:
        xScale = 1.0f;
        break;
    case MAT_eTransform_Zoom:
    case MAT_eTransform_Scale:
        xScale = _hTransform->stScaleVector.xY;
        break;
    case MAT_eTransform_RotationZoom:
    case MAT_eTransform_RotationScale:
    case MAT_eTransform_ComplexRotationScale:
        {
            float x0 = _hTransform->stTransformMatrix.stCol_0.xY;
            float x2 = _hTransform->stTransformMatrix.stCol_2.xY;
            float x1 = _hTransform->stTransformMatrix.stCol_1.xY;
            float xSqr = x0 * x0 + x1 * x1 + x2 * x2;
            MTH_SQRT_TO(xScale, xSqr);
        }
        break;
    default:
        xScale = 0.0f;
    }

    return xScale;
}

float fn_xAngleVectorVertical(MTH3D_tdstVector_* stVectorU, MTH3D_tdstVector_* stVectorV)
{
    float xNorm;
    MTH3D_tdstVector_ VectTmp;
    MTH3D_tdstVector_ vW;
    MTH3D_tdstVector_ vN;
    MTH3D_tdstVector_ vV;
    MTH3D_tdstVector_ vU;
    float xAngle;
    float xCos;
    if ((stVectorU->xX == 0.0f) && (stVectorU->xY == 0.0f))
    {
        if ((stVectorV->xX == 0.0f) && (stVectorV->xY == 0.0f)) { return 0.0f; }
        MTH3D_M_vCopyVector(&vU, stVectorV);
        MTH3D_M_vCopyVector(&vV, stVectorU);
    }
    else
    {
        MTH3D_M_vCopyVector(&vU, stVectorU);
        MTH3D_M_vCopyVector(&vV, stVectorV);
    }
    MTH_SQR3_OF(xNorm, vU);
    MTH_SQRT_TO(xCos, xNorm);
    if (xCos != 0.0f)
    {
        xCos = 1.0f / xCos;
        vU.xX = xCos * vU.xX;
        vU.xY = xCos * vU.xY;
        vU.xZ = xCos * vU.xZ;
    }
    MTH_SQR3_OF(xNorm, vV);
    MTH_SQRT_TO(xAngle, xNorm);
    if (xAngle != 0.0f)
    {
        xAngle = 1.0f / xAngle;
        vV.xX = xAngle * vV.xX;
        vV.xY = xAngle * vV.xY;
        vV.xZ = xAngle * vV.xZ;
    }
    MTH_CROSS_COMPONENT_TO(VectTmp.xX, vU.xX, vVectorZ.xZ, vU.xY, vVectorZ.xY);
    MTH_CROSS_COMPONENT_TO(VectTmp.xY, vU.xY, vVectorZ.xX, vU.xZ, vVectorZ.xZ);
    MTH_CROSS_COMPONENT_TO(VectTmp.xZ, vU.xZ, vVectorZ.xY, vU.xX, vVectorZ.xX);
    MTH_CROSS_COMPONENT_TO(vW.xX, vV.xX, vVectorZ.xZ, vV.xY, vVectorZ.xY);
    MTH_CROSS_COMPONENT_TO(vW.xY, vV.xY, vVectorZ.xX, vV.xZ, vVectorZ.xZ);
    MTH_CROSS_COMPONENT_TO(vW.xZ, vV.xZ, vVectorZ.xY, vV.xX, vVectorZ.xX);
    MTH_SQR3_OF(xNorm, VectTmp);
    MTH_SQRT_TO(xCos, xNorm);
    MTH_SQR3_OF(xNorm, vW);
    MTH_SQRT_TO(xAngle, xNorm);
    MTH_DOT3_OF(xNorm, VectTmp, vW);
    if (xNorm > 1.0f) { xNorm = 1.0f; }
    if (xNorm < -1.0f) { xNorm = -1.0f; }
    xCos = acosf(xNorm);
    if (vU.xZ < vV.xZ) { xCos = -xCos; }
    return xCos;
}

