    if (ulIndChar < pCheapList->NumberOfCheapCharacter) {
        pc = (char*)pCheapList;
        pc = pc + 0x34;
        if (eProcedureId == 846)
            ((char*)pc)[ulIndChar * 48] = 1;
        else
            ((char*)pc)[ulIndChar * 48] = 0;
    }
    return p_stTree;
}

