void fn_vNextSelectionNoWrap(void)
{
    unsigned int u32Sound2Play;

    u32Sound2Play = 2;

    if (g_CurrentSelection == aMenu2DPages[g_CurrentMenu2DPage].NbSelection - 1)
    {
        if (aMenu2DPages[g_CurrentMenu2DPage].NbSelection == aMenu2DPages[g_CurrentMenu2DPage].NbEntry)
        {
            u32Sound2Play = 10;
        }
        else
        {
            if (aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry !=
                aMenu2DPages[g_CurrentMenu2DPage].NbEntry - aMenu2DPages[g_CurrentMenu2DPage].NbSelection)
            {
                aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry++;
            }
            else
            {
                u32Sound2Play = 10;
            }
        }
    }
    else
    {
        g_CurrentSelection++;
    }

    fn_vPlaySoundInGameMenu2D(u32Sound2Play);

    if (aMenu2DPages[g_CurrentMenu2DPage].abGrayed[g_CurrentSelection] != 0)
    {
        u32Sound2Play = 2;

        if (g_CurrentSelection == aMenu2DPages[g_CurrentMenu2DPage].NbSelection - 1)
        {
            if (aMenu2DPages[g_CurrentMenu2DPage].NbSelection == aMenu2DPages[g_CurrentMenu2DPage].NbEntry)
            {
                u32Sound2Play = 10;
            }
            else
            {
                if (aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry !=
                    aMenu2DPages[g_CurrentMenu2DPage].NbEntry - aMenu2DPages[g_CurrentMenu2DPage].NbSelection)
                {
                    aMenu2DPages[g_CurrentMenu2DPage].CurrentFirstEntry++;
                }
                else
                {
                    u32Sound2Play = 10;
                }
            }
        }
        else
        {
            g_CurrentSelection++;
        }

        fn_vPlaySoundInGameMenu2D(u32Sound2Play);

        if (aMenu2DPages[g_CurrentMenu2DPage].abGrayed[g_CurrentSelection] != 0)
        {
            fn_vNextSelectionNoWrap();
        }
    }
}

tdstNodeInterpret_* fn_p_stDotOperator(HIE_tdstSuperObject_* p_SuperObjPerso, tdstNodeInterpret_* p_stTree, tdstGetSetParam_* p_stValue)
{
    unsigned char ucOk;
    HIE_tdstSuperObject_* hSuperObjPerso;
    tdeTypeInterpret_ eTypeInterpret;
    tdstNodeInterpret_* p_stNext;

    p_stTree = fn_p_stOperatorGetPerso(p_SuperObjPerso, p_stTree, &hSuperObjPerso);
    p_stNext = p_stTree;
    eTypeInterpret = (tdeTypeInterpret_)p_stTree->eType;
    if (eTypeInterpret == E_ti_DsgVarRef)
    {
        fn_ucGetDsgVar(p_stTree->uDummy.uParam.ucValue, 0, hSuperObjPerso->hLinkedObject.p_stCharacter->h_Brain->p_stMind, p_stValue);
        p_stNext = p_stTree + 1;
        return p_stNext;
    }
    else if (eTypeInterpret == E_ti_Field)
    {
        p_stNext = p_stTree + 1;
        ucOk = fn_ucGetFieldValue(p_stTree->uDummy.uId.eFieldId, hSuperObjPerso, p_stValue);
        if (!ucOk)
        {
            fn_vOnAIErm_M_UpdateLastError(0x22, 0);
        }
    }
    else if (eTypeInterpret == E_ti_Operator)
    {
        if (p_stTree->uDummy.uId.eFuncId == eFunc_Cosinus)
        {
            p_stNext = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, p_stValue);
        }
    }
    return p_stNext;
}

void VU1UpdateDiffuseOnlyParam(tagGLcontext* pctx)
{
    tag_GLlight* pLight;
    tag_stVU1MatriceL* pstMatriceL;
    int iLoop;
    unsigned int nLightBits;
    tag_GLmaterial* pmat;
    float vTmp1[4];
    float vTmp2[4];
    nLightBits = pctx->nLightBits;
    pstMatriceL = (tag_stVU1MatriceL*)pctx->pVIFIBufTail;
    pctx->bLightsChanged = 0;
    pctx->bMaterialChanged = 0;
    if (pctx->nLightBits & 0x200)
    {
        pmat = &pctx->Materials[0];
        sceVu0CopyVector(pctx->pvAmbient[0], pctx->vAmbient);
        pLight = &pctx->Lights[0];
        for (iLoop = 0; iLoop < 4; iLoop++, pLight++)
        {
            if (nLightBits & (1 << iLoop))
            {
                if (pctx->eColorMaterialMode == 0x1200 || pctx->eColorMaterialMode == 0x1602)
                {
                    sceVu0AddVector(pctx->pvAmbient[0], pLight->vAmbient, pctx->pvAmbient[0]);
                }
                else
                {
                    sceVu0MulVector(vTmp1, pLight->vAmbient, pmat->vAmbient);
                    sceVu0AddVector(pctx->pvAmbient[0], vTmp1, pctx->pvAmbient[0]);
                }
                if (pctx->eColorMaterialMode == 0x1201 || pctx->eColorMaterialMode == 0x1602)
                {
                    sceVu0CopyVector(pstMatriceL->mDiffuseLightColor[iLoop], pLight->vDiffuse);
                }
                else
                {
                    sceVu0MulVector(pstMatriceL->mDiffuseLightColor[iLoop], pmat->vDiffuse, pLight->vDiffuse);
                }
                sceVu0CopyVector(pstMatriceL->mDiffuseLightPosition[iLoop], pLight->vPosition);
            }
            else
            {
                sceVu0CopyVector(pstMatriceL->mDiffuseLightColor[iLoop], vZero);
                sceVu0CopyVector(pstMatriceL->mDiffuseLightPosition[iLoop], vZero);
            }
        }
    }
    else
    {
        pmat = &pctx->Materials[0];
        sceVu0CopyVector(pctx->pvAmbient[0], pctx->vAmbient);
        pLight = &pctx->Lights[0];
        for (iLoop = 0; iLoop < 4; iLoop++, pLight++)
        {
            if (nLightBits & (1 << iLoop))
            {
                sceVu0MulVector(vTmp2, pmat->vAmbient, pLight->vAmbient);
                sceVu0AddVector(pctx->pvAmbient[0], vTmp2, pctx->pvAmbient[0]);
                sceVu0MulVector(pstMatriceL->mDiffuseLightColor[iLoop], pmat->vDiffuse, pLight->vDiffuse);
                sceVu0CopyVector(pstMatriceL->mDiffuseLightPosition[iLoop], pLight->vPosition);
            }
            else
            {
                sceVu0CopyVector(pstMatriceL->mDiffuseLightPosition[iLoop], vZero);
                sceVu0CopyVector(pstMatriceL->mDiffuseLightColor[iLoop], vZero);
            }
        }
    }
    pctx->pvAmbient[0][3] = pmat->vDiffuse[3];
    sceVu0TransposeMatrix(pstMatriceL->mDiffuseLightPosition, pstMatriceL->mDiffuseLightPosition);
    pstMatriceL->ivUnpackCode[0] = pstMatriceL->ivUnpackCode[1] = 0;
    pstMatriceL->ivUnpackCode[2] = 0x01000404;
    pstMatriceL->ivUnpackCode[3] = 0x6C08000C;
    pctx->pVIFIBufTail += 9;
}

void fn_vDestroyAllHierarchy(HIE_tdstSuperObject_* p_stSuperObject)
{
    HIE_tdstSuperObject_* p_stNextChild;
    HIE_tdstSuperObject_* p_stChild;
    tdstEngineObject_* p_stCharacter;
    int i;
    extern HIE_tdstSuperObject_* HIE_fn_hForceGetSuperObjectNextBrother(HIE_tdstSuperObject_* hSuperObject);
    extern void HIE_fn_vIsolate(HIE_tdstSuperObject_* p_stSuperObject);
    extern unsigned char fn_ucIsAnAlwaysObject(tdstEngineObject_* p_stObject);
    extern int fn_bIsInFix(tdstEngineObject_* p_stObject);
    extern void fn_vDesinitOneObject(tdstEngineObject_* p_stObject, int eObjIniType);
    extern void Erm_fn_v_UpdateLastError(unsigned short uwStartOfWarningsId, unsigned char ucModuleId, unsigned int ulChannelId, unsigned short uwErrNum, int lDebugInfo, unsigned char ucOpenInfoWindow, unsigned char ucStopForDebug, char* szPersonalMsg);
    extern tdstStructureHandleFunction_ g_a_stStructureHandleFunction[12];
    extern unsigned char g_ucGameModuleId;

    p_stChild = p_stSuperObject->hFirstElementDyn;
    p_stNextChild = HIE_fn_hForceGetSuperObjectNextBrother(p_stChild);
    if (p_stChild != (HIE_tdstSuperObject_*)0)
    {
        do
        {
            fn_vDestroyAllHierarchy(p_stChild);
            p_stChild = p_stNextChild;
            p_stNextChild = HIE_fn_hForceGetSuperObjectNextBrother(p_stChild);
        } while (p_stChild != (HIE_tdstSuperObject_*)0);
    }
    HIE_fn_vIsolate(p_stSuperObject);
    if (p_stSuperObject->ulTypeOfLinkedObject == 2)
    {
        if (!fn_ucIsAnAlwaysObject(p_stSuperObject->ulTypeOfLinkedObject != 2 ? 0 : p_stSuperObject->hLinkedObject.p_stCharacter))
        {
            if (fn_bIsInFix(p_stSuperObject->ulTypeOfLinkedObject != 2 ? 0 : p_stSuperObject->hLinkedObject.p_stCharacter))
            {
                fn_vDesinitOneObject(p_stSuperObject->ulTypeOfLinkedObject != 2 ? 0 : p_stSuperObject->hLinkedObject.p_stCharacter, 1);
            }
            else
            {
                if (p_stSuperObject->ulTypeOfLinkedObject == 2)
                {
                    p_stCharacter = p_stSuperObject->hLinkedObject.p_stCharacter;
                    for (i = 10; i >= 0; i--)
                    {
                        if (((void**)p_stCharacter)[i] != 0)
                        {
                            g_a_stStructureHandleFunction[i].p_fn_vFreeFunction(p_stCharacter);
                        }
                    }
                }
                else
                {
                    Erm_fn_v_UpdateLastError(0x30, g_ucGameModuleId, 0, 0x39, -1, 0xFF, 0xFF, NULL);
                }
            }
        }
    }
    if (p_stSuperObject->ulTypeOfLinkedObject == 2)
    {
        if (fn_ucIsAnAlwaysObject(p_stSuperObject->ulTypeOfLinkedObject != 2 ? 0 : p_stSuperObject->hLinkedObject.p_stCharacter))
        {
            return;
        }
        if (fn_bIsInFix(p_stSuperObject->ulTypeOfLinkedObject != 2 ? 0 : p_stSuperObject->hLinkedObject.p_stCharacter))
        {
            fn_vDesinitOneObject(p_stSuperObject->ulTypeOfLinkedObject != 2 ? 0 : p_stSuperObject->hLinkedObject.p_stCharacter, 1);
        }
    }
}

