float fn_xRealModuloAround(float xFrom, float xModulus, float xValue)
{
    xValue -= xFrom;
    while (xValue < 0.0f) {
        xValue += xModulus;
    }
    while (xValue >= xModulus) {
        xValue -= xModulus;
    }
    xValue += xFrom;
    return xValue;
}

