    }
    xZ = stVertex1.xZ; xX = stVertex1.xX; xY = stVertex1.xY;
    switch (ucFlags & 7) {
    case 1:
        return xX;
    case 2:
        return xY;
    case 4:
        return xZ;
    case 3:
        MTH_SQR2_TO(xX, xX, xY);
        break;
    case 5:
        MTH_SQR2_TO(xX, xX, xZ);
        break;
    case 6:
        MTH_SQR2_TO(xX, xY, xZ);
        break;
    case 0:
        return 0.0f;
    case 7:
        MTH_SQR3_TO(xX, xX, xY, xZ);
        break;
    }
    MTH_SQRT_TO(xDist, xX);
    return xDist;
}

