unsigned char fn_ucGetFieldOrientation(HIE_tdstSuperObject_* hSuperObjPerso, tdstGetSetParam_* p_stGetSetParam)
{
    float xNorm;
    MTH3D_tdstVector_ stVertexDirection;
    MTH3D_tdstVector_ stVertex;
    MTH3D_tdstVector_* p_stTrans;

    MTH3D_M_vSetVectorElements(&stVertexDirection, 0.0f, -1.0f, 0.0f);
    MAT_fn_vApplyOnVertex(&stVertexDirection, hSuperObjPerso->hGlobalMatrix, &stVertexDirection);

    {
        p_stTrans = POS_fn_p_stGetTranslationVector(hSuperObjPerso->hGlobalMatrix);
        ((int*)&stVertex)[0] = ((int*)p_stTrans)[0];
        ((int*)&stVertex)[1] = ((int*)p_stTrans)[1];
        ((int*)&stVertex)[2] = ((int*)p_stTrans)[2];
    }

    MTH3D_M_vSubVector(&stVertexDirection, &stVertexDirection, &stVertex);
    xNorm = MTH_xSqrt(MTH_xSqr3(stVertexDirection.xX, stVertexDirection.xY, stVertexDirection.xZ));
    if (xNorm != 0.0f)
    {
        MTH3D_M_vMulScalarVector(&stVertexDirection, 1.0f / xNorm, &stVertexDirection);
    }
    ((int*)p_stGetSetParam)[0] = *(int*)&stVertexDirection.xX;
    ((int*)p_stGetSetParam)[1] = *(int*)&stVertexDirection.xY;
    ((int*)p_stGetSetParam)[2] = *(int*)&stVertexDirection.xZ;
    *(tdeVariableType_*)((char*)p_stGetSetParam + 12) = E_vt_Vector;
    return 1;
}

void GLI_vSinusEffetOn3DVertex(MTH3D_tdstVector_* p_stVertex3D)
{
    float fFreq;
    float xZ;
    float xY;
    float xX;
    int lVertice;

    fFreq = GLI_fF2pow24 + (a3_xSinEffectBaseMesh[0] + (p_stVertex3D->xY * g_xSinusSizeMuly.f + p_stVertex3D->xZ * g_xSinusSizeMulz.f));
    lVertice = *(int*)&fFreq & 0x1FF; xX = p_stVertex3D->xX + stSinEffectAmp.v.xX * a64_fSinTable[lVertice];
    fFreq = GLI_fF2pow24 + (a3_xSinEffectBaseMesh[1] + (p_stVertex3D->xZ * g_xSinusSizeMulz.f + p_stVertex3D->xX * g_xSinusSizeMulx.f));
    lVertice = *(int*)&fFreq & 0x1FF; xY = p_stVertex3D->xY + stSinEffectAmp.v.xY * a64_fSinTable[lVertice];
    fFreq = GLI_fF2pow24 + (a3_xSinEffectBaseMesh[2] + (p_stVertex3D->xY * g_xSinusSizeMuly.f + p_stVertex3D->xX * g_xSinusSizeMulx.f));
    lVertice = *(int*)&fFreq & 0x1FF; xZ = p_stVertex3D->xZ + stSinEffectAmp.v.xZ * a64_fSinTable[lVertice];
    p_stVertex3D->xX = xX;
    p_stVertex3D->xY = xY;
    p_stVertex3D->xZ = xZ;
}

unsigned int fn_uiGetSomeBytes(unsigned int* _puiArray, unsigned int NbInts, unsigned int SomeOtherValue)
{
    unsigned int Seeds[6];
    unsigned int i;
    unsigned int j;

    Seeds[0] = g_uiAnotherRandom;
    Seeds[1] = g_stEngineStructure.ulRealTimeLowPart;
    Seeds[2] = g_stEngineStructure.ulTrameNumber;
    Seeds[3] = (unsigned int)(12345.0f * g_stEngineStructure.h_StdCamCaracter->hGlobalMatrix->xTranslationY);
    Seeds[4] = (unsigned int)_puiArray;
    Seeds[5] = SomeOtherValue;

    for (i = 0; i < NbInts; i++)
    {
        Seeds[0] = (Seeds[0] * 0x126CDD7 + 0x1E240) | 1;
        for (j = 1; j < 6; j++)
            Seeds[j] = Seeds[j - 1] ^ ((Seeds[j] + (Seeds[j - 1] >> 7)) * 0x127C3D1);
        _puiArray[i] = Seeds[5];
    }

    return _puiArray[i - 1];
}

void impPS2glFogfv(unsigned int pname, float* params)
{
    int ivFogColor[4];

    if (pname == 0x0B66) /* GL_FOG_COLOR */
    {
        ivFogColor[0] = (int)(255.0f * fogClamp01(params[0]));
        ivFogColor[1] = (int)(255.0f * fogClamp01(params[1]));
        ivFogColor[2] = (int)(255.0f * fogClamp01(params[2]));

        *(tag_int4*)&g_PS2glContext.ivFogColor = *(tag_int4*)ivFogColor;

        g_gsContext.FOGCOL.FCR = (char)ivFogColor[0]; g_gsContext.ModFlgs.FOGCOL_Modified = 1;
        g_gsContext.FOGCOL.FCG = (char)ivFogColor[1]; g_gsContext.ModFlgs.FOGCOL_Modified = 1;
        g_gsContext.FOGCOL.FCB = (char)ivFogColor[2]; g_gsContext.ModFlgs.FOGCOL_Modified = 1;

        /* The retail binary keeps a second, unreachable copy of the fog
         * parameter switch here: it reads the colour array that was just
         * filled instead of params[].  The test is always false in this
         * branch, but the retail compiler still emits it. */
        if (pname != 0x0B66)
        {
            switch (pname)
            {
            case 0x0B65: /* GL_FOG_MODE */
                g_PS2glContext.eFogMode = ivFogColor[0];
                break;
            case 0x0B62: /* GL_FOG_DENSITY */
                g_PS2glContext.fFogDensity = (float)ivFogColor[0];
                break;
            case 0x0B63: /* GL_FOG_START */
                g_PS2glContext.fFogLinearStart = (float)ivFogColor[0];
                break;
            case 0x0B64: /* GL_FOG_END */
                g_PS2glContext.fFogLinearEnd = (float)ivFogColor[0];
                break;
            case 0x0B61: /* GL_FOG_INDEX */
                g_PS2glContext.fFogIndex = (float)ivFogColor[0];
                break;
            default:
                return;
            }
            g_PS2glContext.bFogChanged = 1;
        }
    }
    else
    {
        float fValue = params[0];
        switch (pname)
        {
        case 0x0B65: /* GL_FOG_MODE */
            /* The retail code inlines the float-to-unsigned conversion; spell
             * it out so the compiler does not call fptoui. */
            if (2147483648.0f <= fValue)
            {
                g_PS2glContext.eFogMode = 0x80000000u | (unsigned int)(int)(fValue - 2147483648.0f);
            }
            else
            {
                g_PS2glContext.eFogMode = (unsigned int)(int)fValue;
            }
            break;
        case 0x0B62: /* GL_FOG_DENSITY */
            g_PS2glContext.fFogDensity = fValue;
            break;
        case 0x0B63: /* GL_FOG_START */
            g_PS2glContext.fFogLinearStart = fValue;
            break;
        case 0x0B64: /* GL_FOG_END */
            g_PS2glContext.fFogLinearEnd = fValue;
            break;
        case 0x0B61: /* GL_FOG_INDEX */
            g_PS2glContext.fFogIndex = fValue;
            break;
        default:
            return;
        }
        g_PS2glContext.bFogChanged = 1;
    }
}

