    {
        Erm_fn_v_UpdateLastError(0x43, g_ucAIModuleId, 0, 0x4D, -1, 0xFF, 0, "Morphing requires objects with the same number of points"); Erm_fn_ClearLastError(0);
    }

    return (tdstNodeInterpret_ *)iTreeResult;
}

