unsigned char impPS2glAreTexturesResident(int n, unsigned int* textures, unsigned char* residences)
{
    unsigned int tex;
    unsigned char bAll;
    unsigned char bRes;
    int I;

    bAll = 1;
    for (I = 0; I < n; I++)
    {
        tex = *textures++;
        if ((tex < 0x200) && (bAll != 0))
        {
            bRes = (g_PS2glContext.aTexName[tex].bResident != 0) && (g_PS2glContext.aTexName[tex].bAllocated != 0);
            *residences = bRes;
            bAll = (bRes != 0);
        }
        residences++;
    }
    return bAll;
}

