void SCT_fn_vSendSectorToViewportDynamic(MTH3D_tdstVector_* _p_stAbsolutePositionOfCamera, GLD_tdstViewportAttributes_* _p_stVpt, HIE_tdstSuperObject_* _hSprObjSector, int _lDrawMask, int _lCullingResult)
{
    short xI;
