tdstNodeInterpret_* fn_p_stModuleControlProcedure(HIE_tdstSuperObject_* p_SuperObjPerso, tdstNodeInterpret_* p_stTree)
{
    int lModuleId;
    tdeProcedureId_ eProcedureId;
    tdstGetSetParam_ stParam1 = {0};

    eProcedureId = (p_stTree - 1)->uDummy.uId.eProcedureId;

    if (eProcedureId != eProc_ReleaseAllModulesControl)
        p_stTree = fn_p_stEvalTree(p_SuperObjPerso, p_stTree, &stParam1);

    switch (eProcedureId)
    {
    case eProc_TakeManyModulesControl:
        lModuleId = stParam1.uDummy.uParam.lValue;
        lModuleId--;
        while (lModuleId >= 0)
        {
            fn_vTakeControlOfChannel(p_SuperObjPerso->hLinkedObject.p_stCharacter, lModuleId, 1);
            lModuleId--;
        }
        return p_stTree;
    case eProc_TakeModuleControl:
        fn_vTakeControlOfChannel(p_SuperObjPerso->hLinkedObject.p_stCharacter, stParam1.uDummy.uParam.uwValue, 1);
        return p_stTree;
    case eProc_ReleaseModuleControl:
        fn_vTakeControlOfChannel(p_SuperObjPerso->hLinkedObject.p_stCharacter, stParam1.uDummy.uParam.uwValue, 0);
        return p_stTree;
    case eProc_ReleaseAllModulesControl:
        fn_vTakeControlOfChannel(p_SuperObjPerso->hLinkedObject.p_stCharacter, 0xffff, 0);
        return p_stTree;
    }

    return p_stTree;
}

unsigned char INT_fn_bIntersectSegmentWithTriangle(MTH3D_tdstVector_* p_stVertexA, MTH3D_tdstVector_* p_stVectAB, MTH3D_tdstVector_* p_stVertex1, MTH3D_tdstVector_* p_stVertex2, MTH3D_tdstVector_* p_stVertex3, MTH3D_tdstVector_* p_stNormal, float xDPlan, float* p_xT, MTH3D_tdstVector_* p_stHit)
{
    float xDivid;
    float xDot;

    if (!INT_fn_bFastRejectIntersectSegmentWithTriangle(p_stVertexA, p_stVectAB, p_stVertex1, p_stVertex2, p_stVertex3))
        return 0;

    xDot = MTH_xDot3(p_stNormal->xX, p_stVectAB->xX, p_stNormal->xY, p_stVectAB->xY, p_stNormal->xZ, p_stVectAB->xZ);
    if (xDot < 0.0f)
    {
        xDivid = xDPlan + MTH_xDot3(p_stNormal->xX, p_stVertexA->xX, p_stNormal->xY, p_stVertexA->xY, p_stNormal->xZ, p_stVertexA->xZ);
        if (xDivid > 0.0f)
        {
            if (xDivid < -xDot)
            {
                xDivid = xDivid / xDot;
                xDivid = -xDivid;

                p_stHit->xX = p_stVertexA->xX + xDivid * p_stVectAB->xX;
                p_stHit->xY = p_stVertexA->xY + xDivid * p_stVectAB->xY;
                p_stHit->xZ = p_stVertexA->xZ + xDivid * p_stVectAB->xZ;

                if (INT_fn_bGetPointInTriangle(p_stHit, p_stVertex1, p_stVertex2, p_stVertex3, p_stNormal))
                {
                    *p_xT = xDivid;
                    return 1;
                }
                return 0;
            }
        }
        return 0;
    }
    return 0;
}

