    for (ucModuleId = 0; ucModuleId < g_ucErmNbOfModule && *p_uwModuleBlockId == 0xFFFF; ucModuleId++) {
        a_stMyBlockInfo = (tdstBlockInfoPriv_*)g_a_p_stMmgModuleBlocksInfo[ucModuleId];
