    unsigned int ulCounter;
    tdstDynam_* h_Dynam;
    tdstGetSetParam_ stValue;
    unsigned int ulMaxList;
    DNM_stDynamics* pstDynamic;
    MTH3D_tdstVector_* p_stVector;
    int lNoDynam;
