            if ((lNoDynam != 0) ^ 1)
                return p_stTree;
            pstDynamic = fn_p_stDynamGetDynamics(h_Dynam);
            stVector.v.xX = pstDynamic->m_uStreamSpeed.v.xX + p_stVector->xX;
